def memoized(f):
    cache = {}
    def wrapped(k):
    v = cache . get(k)
    if v is None:
    v = cache[k] = f(k)
    return v
    return wrapped
    @ memoized
    def fibonacci(n):
    if n in [0, 1]:
    return n
    return fibonacci(n - 1) + fibonacci(n - 2)

