    def rc(x, y, i):
    if i == len(word):
        return True
    if grid[x][y] != word[i]:
        return False
    grid[x][y] = ''
    r = any(rc(x + u, y + v, i + 1)
            for u in range(- 1, 2)
            for v in range(- 1, 2))
