from re import compile
REGEX = compile(r"(-?\d*)(x?)\^?(-?\d*)"). fullmatch


def differentiate(poly):
    a, x, n = REGEX(poly). groups()
    a, n = int(- 1 if a == '-' else a or 1), int(n or bool(x))
    if n == 0 or n == 1:
        return f" { a * n } "
    if n == 2:
        return f" { a * n } x"
    return f" { a * n } x^ { n - 1 } "

