from collections import Counter
from random import randrange
from math import gcd, lcm, log, log2


def miller_rabin_test(n):
    if n < 2 or not n % 2 or not n % 3:
    return n in (2, 3)
    k, r, d = 5, 0, n - 1
    while d % 2 == 0:
    d / /= 2
    r += 1
    while k >= 1:
    k -= 1
    a = randrange(2, n - 1)
    x = pow(a, d, n)
    if x == 1 or x == n - 1:
    continue
    m = r - 1
    while m >= 1:
    m -= 1
    x = pow(x, 2, n)
    if x == n - 1:
    break
    else:
    return False
    return True
    def is_prime(n):
    return miller_rabin_test(n)

    def pollard_rho(n):
    while True:
    x, c = randrange(1, n), randrange(1, n)
    def f(x): return (x * x + c) % n
    y = f(x)
    while (d := gcd(abs(x - y), n)) == 1:
    x, y = f(x), f(f(y))
    if d != n:
    return d
    def factor(n):
    if is_prime(n):
        return Counter([n])
    return factor(r := pollard_rho(n)) + factor(n / / r)

    def divisor(n, psm):
    ps = []
    for p, k in psm . items():
    for i in range(k):
    ps . append(p)
    ds = set([1, n])
    def go(i, d):
    if i < len(ps):
    ds . add(d * ps[i])
    go(i + 1, d)
    go(i + 1, d * ps[i])
    go(0, 1)
    return sorted(list(ds))

    def binary_raise(n, p):
    r = 1
    while p > 0:
    if (p & 1) == 1:
    r *= n
    p >>= 1
    n *= n
    return r
    def ext_euclidean(a, b):
    x, y, u, v = 0, 1, 1, 0
    while a != 0:
    q, r = b / / a, b % a
    m, n = x - u * q, y - v * q
    a, b, x, y, u, v = r, a, u, v, m, n
    return b, x, y
    def fast_mul(a, b, p):
    q, r = a
    s, t = b
    x = q * s + 5 * r * t
    y = q * t + r * s
    return (x % p, y % p)

    def fast_plus(a, n, p):
    r = (1, 0)
    while n > 0:
    if (n & 1) == 1:
    r = fast_mul(r, a, p)
    n >>= 1
    a = fast_mul(a, a, p)
    return r
    def fib_mod(n, p):
    _, q, _ = ext_euclidean(pow(2, n, p), p)
    q %= p
    ns = fast_plus((1, 1), n, p)
    return fast_mul(ns, (q, 0), p)

    def prime_pisano(n):
    if n == 2:
        return 3
    r = n % 5
    q = 4 * n if not r else n - 1 if r in (1, 4) else 2 * (n + 1)
    if not r:
        return q
    ps = factor(q)
    ds = divisor(q, ps)
    for d in ds:
    if fib_mod(d, n) == (1, 0):
    return d
    def composite_pisano(n):
    ps, m = factor(n), 1
    for p, k in ps . items():
    m = lcm(m, binary_raise(p, k - 1) * prime_pisano(p))
    return m
    def pisano_period(n):
    if n == 1:
        return 1
    eps, p2, p5 = 1e-9, log2(n), log(n) / log(5)
    if p2 % 1 < eps:
        return 3 * (2 * * (round(p2) - 1))
    if p5 % 1 < eps:
        return 4 * (5 * * round(p5))
    return composite_pisano(n)

    # initial method name of the kata
    PisanoPeriod = pisano_period

