from itertools import accumulate


def ways_in_3d_matrix(x, y, z):
    x, y, z = sorted((x, y, z))

    layer = [[int(j == 0 or k == 0) for k in range(z)] for j in range(y)]
    for j in range(1, y):
    for k in range(1, z):
    layer[j][k] = layer[j - 1][k] + layer[j][k - 1]

    seq = [1] * (y + z - 1)
    for _ in range(x - 1):
    seq = [* accumulate(seq)]

    return layer[- 1][- 1] * seq[- 1]

