    res, idx = [x] * x, 1
    elif (x := next(seq)) != 1:
    res, idx = [x] * 2 + [0] * x + [x] * (x - 2), 2
    else:
    res, idx = [1, (x := next(seq)), 1, 0] + [1] * (x - 2), 3
    while len(res) < n and (x := next(seq)):
