def packing_rectangles(* args):
    result, inputs = float("inf"), {
        args[: 2], args[2: 4], args[4:], args[1:: - 1], args[3: 1: - 1], args[: 3: - 1]}
    for a, b, c, d, e, f in permutations(args):
    if (a, b) in inputs and (c, d) in inputs and (e, f) in inputs:
    result = min(result, (a + c + e) * max(b, d, f),
                 (a + max(c, e)) * max(b, d + f))
    return result

