    def __init__(self):
    self . suits = tuple('CDHS')
    self . ranks = tuple('A23456789TJQK')
    self . cards = tuple(r + s for s in self . suits for r in self . ranks)

    def __len__(self) - > int:
    return len(self . cards)

    def find_nth_permutation(self, n: int) - > list[str]:
    cards, result = [* self . cards], []
    for i in range(len(self) - 1, - 1, - 1):
    index, n = divmod(n, math . factorial(i))
    result . append(cards . pop(index))
    return result
    def find_ordinal_number_of_permutation(self, state: list[str]) - > int:
    cards, num_of_perm = [* self . cards], 0
    for i, card in zip(count(len(self) - 1, - 1), state):
    index = cards . index(card)
    num_of_perm += index * math . factorial(i)
    _ = cards . pop(index)
    return num_of_perm
    class ValidAlphabet:
    def __init__(self):
    self . valid_symbols = tuple(' ' + string . ascii_uppercase)

    def __len__(self) - > int:
    return len(self . valid_symbols)

    @ cached_property
    def symbols_table(self) - > dict[str, int]:
    return {s: i for i, s in enumerate(self . valid_symbols)}

    @ cached_property
    def indexes_table(self) - > dict[int, str]:
    return {i: s for s, i in self . symbols_table . items()}

    class PlayingCards:
    ALPHA = ValidAlphabet()
    DECK = Deck()

    @ classmethod
    def encode(cls, message: str) - > list[str]:
    k, rm = len(cls . ALPHA), reversed(message)
    perm_n = sum(
        cls . ALPHA . symbols_table[s] * k * * i for i, s in enumerate(rm)
    )
    return cls . DECK . find_nth_permutation(perm_n)

    @ classmethod
    def decode(cls, deck: list[str]) - > str:
    n = cls . DECK . find_ordinal_number_of_permutation(deck)
    result = []
    while n:
    n, index = divmod(n, len(cls . ALPHA))
    result . append(cls . ALPHA . indexes_table[index])
    return '' . join(reversed(result))

from string import ascii_uppercase


class CardChameleon:

    __slots__ = ('deck', 'is_valid', 'text')

    ALPHABET = ascii_uppercase + ' '
    BLACK_CARDS = [
        rank + suit for suit in 'CS' for rank in 'A23456789TJQK'] + ['XB']
    RED_CARDS = [
        rank + suit for suit in 'DH' for rank in 'A23456789TJQK'] + ['XR']

    TO_BLACK = dict(zip(ALPHABET, BLACK_CARDS))
    FROM_BLACK = dict(zip(BLACK_CARDS, ALPHABET))
    TO_RED = dict(zip(ALPHABET, RED_CARDS))
    FROM_RED = dict(zip(RED_CARDS, ALPHABET))

    def __init__(self, text: str, deck: list) - > None:
    self . is_valid = set(deck) == self . FROM_BLACK . keys(
    ) | self . FROM_RED . keys() and set(text) <= set(self . ALPHABET)
    self . deck = self . prepare(deck) if self . is_valid else deck
    self . text = text
    def prepare(self, deck) - > list:
    res = [''] * len(deck)
    black, red = [], []
    for card in deck:
        (black if card in self . FROM_BLACK else red). append(card)
    res[0:: 2] = red
    res[1:: 2] = black
    return res
    def swap(self, i: int, j: int) - > None:
    self . deck[i], self . deck[j] = self . deck[j], self . deck[i]

    def shift(self, n: int) - > None:
    self . deck = self . deck[n:] + self . deck[: n]

    def encrypt(self) - > str or None:
    return self . __cipher(self . TO_BLACK, self . FROM_RED, mode=0)

    def decrypt(self) - > str or None:
    return self . __cipher(self . TO_RED, self . FROM_BLACK, mode=1)

    def __cipher(self, to_card: dict, from_card: dict, mode: int) - > str or None:
    if not self . is_valid:
        return None
    res = []
    for char in self . text:
    swap_index = 0
    for i in range(2):
    card = to_card[char]
    index = self . deck . index(card) + mode - 1
    if i ^ mode:
        swap_index = index
    card = self . deck[index + mode]
    char = from_card[card]
    self . swap(0, swap_index), self . shift(2)
    res . append(char)
    return '' . join(res)

def rake_and_burn(days):
