from gmpy2 import digits


def esthetic(num, max_base=10):
    return [base for base in range(2, max_base + 1) if (dig := digits(num, base))
            and all(abs(int(a) - int(b)) == 1 for a, b in zip(dig, dig[1:]))]

def next_palin(n):
    s = str(n)
    l = len(s)
    h = l / / 2
    r = l % 2
    t = s[: h + r] + s[: h][:: - 1]

    if t > s:
    return int(t)
    elif t == '9' * l:
    return 10 * * l + 1
    else:
    m = str(int(s[: h + r]) + 1)
    return int(m + m[: h][:: - 1])

from heapq import heappush, heappop


def closure_gen(* s):
    q = sorted(s)
    m = set(s)
    while q:
    curr = heappop(q)
    yield curr
    for i in s:
    t = curr * i
    if t not in m:
    heappush(q, t)
    m . add(t)

class Weapon:
    def __init__(self, factors):
    self . factors = factors
    self . enhanced = False
    def enhance(self, factors):
    self . factors = [max(a, b) for a, b in zip(self . factors, factors)]
    self . enhanced = True
    def damage(self, characteristics):
    return sum(c * f for c, f in zip(characteristics, self . factors)) + self . factors[3]

    class Character:
    def __init__(self, name='Hero', strength=10, dexterity=10, intelligence=10):
    self . name = name
    self . characteristics = [strength, dexterity, intelligence]
    self . weapons = {'limbs': Weapon([1, 1, 1, 0])}
    self . _best_weapon = None
    self . log = []

    def __getattr__(self, method):
    def wrapper(* args):
    name = method . replace('_', ' '). capitalize()
    if len(args) == 4:
    self . find_weapon(name, args)
    else:
    self . manage_event(name, args)

    return wrapper
    def character_info(self) - > str:
    weapon = self . weapons[self . best_weapon]
    return '\n' . join([self . name, * [f' { c } { v } ' for c, v in zip(['str', 'dex', 'int'], self . characteristics)],
                        f' { self . best_weapon }{[ "" , "(enhanced)" ][ weapon . enhanced ]} { weapon . damage ( self . characteristics )} dmg'])

    def event_log(self) - > str:
    return '\n' . join(self . log)

    def find_weapon(self, name, factors):
    if name in self . weapons:
    self . weapons[name]. enhance(factors)
    else:
    self . weapons[name] = Weapon(factors)
    self . _best_weapon = None
    self . log . append(f" { self . name } finds ' { name } '")

    @ property
    def best_weapon(self):
    if self . _best_weapon is None:
    self . _best_weapon = min(self . weapons . keys(
    ), key=lambda n: (- self . weapons[n]. damage(self . characteristics), n))
    return self . _best_weapon
    def manage_event(self, name, modifiers):
    self . characteristics = [c + m for c,
                              m in zip(self . characteristics, modifiers)]
    self . _best_weapon = None
    self . log . append(f' { name } : ' + ', ' . join(f' { c } { m : + } ' for c,
                        m in zip(['strength', 'dexterity', 'intelligence'], modifiers) if m))

def pop_blocks(lst):
    stk, popping = [], None
    for v in lst:
    if v == popping:
    continue
    if stk and stk[- 1] == v:
    popping = stk . pop()
    else:
    stk . append(v)
    popping = None
    return stk

def asteroid_collision(asteroids):
    i = 0
    while i < len(asteroids):
    if asteroids[i] > 0:
    if i + 1 < len(asteroids) and asteroids[i + 1] < 0:
    s = asteroids[i] + asteroids[i + 1]
    if s > 0:
    asteroids . pop(i + 1)
    else:
    asteroids . pop(i)
    if s == 0:
    asteroids . pop(i)
    i -= 1
    if i >= 0:
        continue
    i += 1
    return asteroids

from preloaded import TreeNode


def build_tree(inorder, postorder):
    if not inorder or not postorder:
    return None
    # Create a hashmap to store the indices of elements in the inorder list
    idx_map = {val: idx for idx, val in enumerate(inorder)}

    def helper(in_start, in_end, post_start, post_end):
    if in_start > in_end or post_start > post_end:
    return None
    root_val = postorder[post_end]
    root = TreeNode(root_val)

    root_index = idx_map[root_val]
    left_size = root_index - in_start
    root . left = helper(in_start, root_index - 1,
                         post_start, post_start + left_size - 1)
    root . right = helper(root_index + 1, in_end,
                          post_start + left_size, post_end - 1)

    return root
    return helper(0, len(inorder) - 1, 0, len(postorder) - 1)

def gimme_the_letters(rng):
    a, b = map(ord, rng . split('-'))
    return '' . join(map(chr, range(a, b + 1)))

def swap_cards(a, b):
    p, q = a / / 10, a % 10
    r, s = b / / 10, b % 10
    return p > q or (r, q) > (p, s)

import re


def numbers_need_friends_too(n):
    return int(re . sub(r'(.)\1*+(?<!\1.)', r'\1' * 3, str(n)))

def min_move(a, b):
    count = 0
    seen = set()
    i = 0
    j = 0
    while j < len(b):
    if a[i] == b[j]:
    i += 1
    j += 1
    elif a[i] in seen:
    i += 1
    else:
    seen . add(b[j])
    j += 1
    count += 1
    return count

