def rev(n, b):
    r = 0
    while n:
        r, n = r * b + n % b, n / / b
    return r

    def prime_reflections(mp, mb): return {b: sum(rev(p, b) < p <= mp and rev(
        p, b) in PRIMES for p in PRIMES) for b in range(2, mb + 1)}

import csv
import shutil
import urllib . request
from collections import defaultdict
from enum import Enum
from zipfile import ZipFile
# constants and helper functions
FILES = 'abcdefgh'
RANKS = '12345678'
ALPHA_NUMS = 'zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen draw'
TEXT_TO_DIGIT = {w: i for i, w in enumerate(ALPHA_NUMS . split())}

# tablebase fetching and processing logic


def prepare_tablebase(url):
    fn = "endgame.zip"
    tablebase = {}
    with urllib . request . urlopen(url) as response, open(fn, 'wb') as out_file:
    shutil . copyfileobj(response, out_file)
    with ZipFile(fn) as zf:
    file = zf . extract('krkopt.data')
    with open(file) as file:
    reader = csv . reader(file)
    for row in reader:
    keys = row[: 6]  # First 6 elements are the positions
    dtm = TEXT_TO_DIGIT . get(row[6], None)
    if dtm is not None:
    tablebase[tuple(keys)] = dtm
    return tablebase
    KRK_TABLEBASE = prepare_tablebase(
        "https://archive.ics.uci.edu/static/public/23/chess+king+rook+vs+king.zip")

    # board symmetry and translation logic

    class Scenario (Enum):
    BASE = 1
    ROT90 = 2
    ROT180 = 3
    ROT270 = 4
    REFLECT1 = 5
    REFLECT2 = 6
    REFLECT3 = 7
    REFLECT4 = 8
    def rotate90(pos):
    f, r = pos
    return FILES[RANKS . index(r)] + RANKS[7 - FILES . index(f)]

    def rotate180(pos):
    f, r = pos
    return FILES[7 - FILES . index(f)] + RANKS[7 - RANKS . index(r)]

    def rotate270(pos):
    f, r = pos
    return FILES[7 - RANKS . index(r)] + RANKS[FILES . index(f)]

    def reflect1(pos):
    f, r = pos
    return FILES[7 - RANKS . index(r)] + RANKS[7 - FILES . index(f)]

    def reflect2(pos):
    f, r = pos
    return f + RANKS[7 - RANKS . index(r)]

    def reflect3(pos):
    f, r = pos
    return FILES[RANKS . index(r)] + RANKS[FILES . index(f)]

    def reflect4(pos):
    f, r = pos
    return FILES[7 - FILES . index(f)] + r
    # Maps for each scenario
    scenario_maps_actual_to_base = {
        Scenario . BASE: {f' { f }{ r } ': f' { f }{ r } ' for f in FILES for r in RANKS},
        Scenario . ROT90: {f' { f }{ r } ': rotate90(f' { f }{ r } ') for f in FILES for r in RANKS},
        Scenario . ROT180: {f' { f }{ r } ': rotate180(f' { f }{ r } ') for f in FILES for r in RANKS},
        Scenario . ROT270: {f' { f }{ r } ': rotate270(f' { f }{ r } ') for f in FILES for r in RANKS},
        Scenario . REFLECT1: {f' { f }{ r } ': reflect1(f' { f }{ r } ') for f in FILES for r in RANKS},
        Scenario . REFLECT2: {f' { f }{ r } ': reflect2(f' { f }{ r } ') for f in FILES for r in RANKS},
        Scenario . REFLECT3: {f' { f }{ r } ': reflect3(f' { f }{ r } ') for f in FILES for r in RANKS},
        Scenario . REFLECT4: {f' { f }{ r } ': reflect4(f' { f }{ r } ') for f in FILES for r in RANKS},
    }

    scenario_maps_actual_to_base
    scenario_maps_base_to_actual = {
        s: {v: k for k, v in scenario_maps_actual_to_base[s]. items()} for s in scenario_maps_actual_to_base
    }

    king_to_scenario_iter = [
        (('a1', 'b1', 'b2', 'c1', 'c2',
          'c3', 'd1', 'd2', 'd3', 'd4'), Scenario . BASE),
        (('a8', 'a7', 'b7', 'a6', 'b6',
          'c6', 'a5', 'b5', 'c5', 'd5'), Scenario . ROT90),
        (('h8', 'g8', 'g7', 'f8', 'f7',
          'f6', 'e8', 'e7', 'e6', 'e5'), Scenario . ROT180),
        (('h1', 'h2', 'g2', 'h3', 'g3',
          'f3', 'h4', 'g4', 'f4', 'e4'), Scenario . ROT270),
        (('h8', 'h7', 'g7', 'h6', 'g6',
          'f6', 'h5', 'g5', 'f5', 'e5'), Scenario . REFLECT1),
        (('a8', 'b8', 'b7', 'c8', 'c7',
          'c6', 'd8', 'd7', 'd6', 'd5'), Scenario . REFLECT2),
        (('a1', 'a2', 'b2', 'a3', 'b3',
          'c3', 'a4', 'b4', 'c4', 'd4'), Scenario . REFLECT3),
        (('h1', 'g1', 'g2', 'f1', 'f2',
          'f3', 'e1', 'e2', 'e3', 'e4'), Scenario . REFLECT4),
    ]

    king_to_scenarios_map = defaultdict(set)

    for kps, s in king_to_scenario_iter:
    for kp in kps:
    king_to_scenarios_map[kp]. add(s)

    class Position:
    def __init__(self, file, rank):
    self . file = file
    self . rank = rank
    @ classmethod
    def from_algebraic(cls, pos_str):
    return cls(pos_str[0], pos_str[1])

    @ classmethod
    def from_indices(cls, fi, ri):
    return cls(FILES[fi], RANKS[ri])

    def to_algebraic(self):
    return f' { self . file }{ self . rank } '
    def to_tuple(self):
    return self . file, self . rank
    def is_immediately_adjacent(self, other):
    fi, ri = FILES . index(self . file), RANKS . index(self . rank)
    foi, roi = FILES . index(other . file), RANKS . index(other . rank)
    return max(abs(fi - foi), abs(ri - roi)) <= 1
    def __repr__(self):
    return self . to_algebraic()

    def __hash__(self):
    return hash(str(self))

    def __eq__(self, other):
    return hash(self) == hash(other)

    def translate_to_base_position(self, scenario):
    return scenario_maps_base_to_actual[scenario][self]

    class PieceType (Enum):
    K = 1
    R = 2
    k = 3
    class ChessPosition:
    def __init__(self, king_pos, rook_pos, opponent_king_pos):
    self . king_pos = Position . from_algebraic(king_pos)
    self . rook_pos = Position . from_algebraic(rook_pos)
    self . opponent_king_pos = Position . from_algebraic(opponent_king_pos)

    self . scenario = None
    self . base_king_pos = None
    self . base_rook_pos = None
    self . base_opponent_king_pos = None
    self . dtm = None
    self . set_scenario()

    if self . dtm is None:
    raise ValueError('Chess position created with no DTM.',
                     king_pos, rook_pos, opponent_king_pos)

    def __repr__(self):
    return f'K { self . king_pos } , R { self . rook_pos } , k { self . opponent_king_pos } '
    def __hash__(self):
    return hash(str(self))

    @ classmethod
    def from_existing(cls, chess_position, piece_type=None, new_position=None):
    king_pos = chess_position . king_pos . to_algebraic()
    rook_pos = chess_position . rook_pos . to_algebraic()
    opponent_king_pos = chess_position . opponent_king_pos . to_algebraic()
    if piece_type is not None:
    if isinstance(new_position, Position):
    pos = new_position . to_algebraic()
    else:
    pos = new_position
    if piece_type . value == 1:
    king_pos = pos
    elif piece_type . value == 2:
    rook_pos = pos
    elif piece_type . value == 3:
    opponent_king_pos = pos
    else:
    raise ValueError(
        'Invalid piece type for new chess position from existing.')
    return cls(king_pos, rook_pos, opponent_king_pos)

    def set_scenario(self):
    for scenario in king_to_scenarios_map[self . king_pos . to_algebraic()]:
    nKf, nKr = self . king_pos . translate_to_base_position(scenario)
    nRf, nRr = self . rook_pos . translate_to_base_position(scenario)
    nkf, nkr = self . opponent_king_pos . translate_to_base_position(scenario)
    dtm = KRK_TABLEBASE . get((nKf, nKr, nRf, nRr, nkf, nkr), None)
    if dtm is not None:
    self . scenario = scenario
    self . base_king_pos = Position(nKf, nKr)
    self . base_rook_pos = Position(nRf, nRr)
    self . base_opponent_king_pos = Position(nkf, nkr)
    self . dtm = dtm
    break
    def translate_position(self):
    if self . scenario:
    return ChessPosition(
        self . base_king_pos . to_algebraic(),
        self . base_rook_pos . to_algebraic(),
        self . base_opponent_king_pos . to_algebraic()
    )
    else:
    raise ValueError('Position does not have an assigned scenario')

    def get_king_moves(self):
    f, r = self . king_pos . to_tuple()
    fi, ri = FILES . index(f), RANKS . index(r)
    Rf, Rr = self . rook_pos . to_tuple()
    Rfi, Rri = FILES . index(Rf), RANKS . index(Rr)
    kf, kr = self . opponent_king_pos . to_tuple()
    kfi, kri = FILES . index(kf), RANKS . index(kr)
    for df in (- 1, 0, 1):
    for dr in (- 1, 0, 1):
    if df or dr:
    fn = fi + df
    rn = ri + dr
    if (
        0 <= fn < 8 and 0 <= rn < 8 and
        (fn, rn) not in ((Rfi, Rri), (kfi, kri)) and
        not Position . from_indices(
            fn, rn). is_immediately_adjacent(self . opponent_king_pos)
    ):
    yield Position . from_indices(fn, rn)

    def get_rook_moves(self):
    f, r = self . rook_pos . to_tuple()
    fi, ri = FILES . index(f), RANKS . index(r)
    Kf, Kr = self . king_pos . to_tuple()
    Kfi, Kri = FILES . index(Kf), RANKS . index(Kr)
    kf, kr = self . opponent_king_pos . to_tuple()
    kfi, kri = FILES . index(kf), RANKS . index(kr)
    for i in range(1, 8):
    if (fi - i, ri) in ((Kfi, Kri), (kfi, kri)) or (fi - i < 0):
    break
    yield Position . from_indices(fi - i, ri)
    for i in range(1, 8):
    if (fi + i, ri) in ((Kfi, Kri), (kfi, kri)) or (fi + i > 7):
    break
    yield Position . from_indices(fi + i, ri)
    for i in range(1, 8):
    if (fi, ri - i) in ((Kfi, Kri), (kfi, kri)) or (ri - i < 0):
    break
    yield Position . from_indices(fi, ri - i)
    for i in range(1, 8):
    if (fi, ri + i) in ((Kfi, Kri), (kfi, kri)) or (ri + i > 7):
    break
    yield Position . from_indices(fi, ri + i)

    def get_all_possible_moves(self):
    for move in self . get_king_moves():
    yield PieceType(1), move
    for move in self . get_rook_moves():
    yield PieceType(2), move
    def _generate_valid_moves(self, strict=True):
    res = []
    for piece_type, pos in self . get_all_possible_moves():
    new_chess_position = ChessPosition . from_existing(self, piece_type, pos)
    if new_chess_position . dtm is not None and self . dtm is not None and (
            ((new_chess_position . dtm < self . dtm + 1) and strict) or new_chess_position . dtm <= self . dtm + 1):
    res . append(new_chess_position)
    return sorted(res, key=lambda pn: pn . dtm)

    def generate_valid_moves(self):
    return vm if (vm := self . _generate_valid_moves()) else self . _generate_valid_moves(False)

    class WhitePlayer:

    def __init__(self, position):
    self . chess_position = None
    self . position_history = []
    self . set_position(ChessPosition(
        * self . parse_initial_position(position)))

    def parse_initial_position(self, position):
    pieces = position . split('-')
    wk_pos, wr_pos = pieces[0]. split(',')
    bk_pos = pieces[1]. strip()
    return wk_pos[1:]. strip(), wr_pos[1:]. strip(), bk_pos[1:]. strip()

    def set_position(self, chess_position):
    self . position_history . append(chess_position)
    self . chess_position = chess_position
    @ property
    def dtm(self):
    return self . chess_position . dtm
    def play(self, black_move):
    new_black_pos_str = black_move[1:]
    self . set_position(ChessPosition . from_existing(
        self . chess_position, PieceType(3), new_black_pos_str))
    for new_position in self . chess_position . generate_valid_moves():
    if new_position . dtm is not None and new_position not in self . position_history[
            max(0, len(self . position_history) - 2):]:
    str_to_return = (
        f'K { new_position . king_pos . to_algebraic ()} ' if new_position . king_pos != self . chess_position . king_pos
        else f'R { new_position . rook_pos . to_algebraic ()} '
    )
    self . set_position(new_position)
    return str_to_return

