               } if n > 1 else {f' { n } '}, len(f' { n : b } ')

    for k in range(ln - 2):
    cand = f' { n - 2 * * k : b } '
    if cand[- k - 2] == '0':
    res . add(cand[: - k - 2] + 'x' + cand[- k - 1:])

    return res

