def solve(arr, k):
    max_mean = 0
    tapir = ()
    for i in range(len(arr) - k + 1):
    sum_slice = 0
    for j in range(len(arr)):
    sum_slice += arr[j]
    if j + 1 >= k + i:
    if sum_slice / (k + i) >= max_mean:
    max_mean = sum_slice / (k + i)
    tapir = (j - (k + i - 1), k + i)
    sum_slice -= arr[j - (k + i - 1)]
    return tapir

