def distribute_seats(num_seats, votes):
    res = [0 for _ in votes]
    for z in range(num_seats):
    mi, _ = max(enumerate(votes), key=lambda p: p[1] / (res[p[0]] + 1))
    res[mi] += 1
    return res

def get_reward(banks: list[tuple[int, int]]):
    fees = 0
    G = dict(banks)
    while G:
    n, (i, j) = 1, G . popitem()
    while j != i:
    n, j = n + 1, G . pop(j)
    fees += n * 2 * * n
    return fees

