def matches_brackets(s):
    c = 0
    for v in s:
    if v == "(":
        c += 1
    if v == ")":
        c -= 1
    if c < 0:
        return False
    return c == 0
    def take_until_close(itr):
    res, c = "", 0
    for v in itr:
    if v == ")" and not c:
        return res
    if v == ")":
        c -= 1
    if v == "(":
        c += 1
    res += v
    def underload(code):
    if not matches_brackets(code):
    raise Exception("Parenthesis don't match")
    stack, output = [], ""
    def iter_code(code):
    code = iter(code)
    for v in code:
    if v == "(":
    stack . append(take_until_close(code))
    continue
    yield v
    if v == "^":
    yield from iter_code(stack . pop())

    for command in iter_code(code):
    if command == ":":
        stack . append(stack[- 1])
    if command == "!":
        stack . pop()
    if command == "~":
        stack . append(stack . pop(- 2))
    if command == "*":
    v = stack . pop()
    stack[- 1] += v
    if command == "a":
        stack[- 1] = f"( { stack [ - 1 ]} )"
    if command == "S":
        output += stack . pop()
    return output

