    return [sum(solved[c] for c in w) for w in s . split()]

def zero_count(sum):
    most = 0
    res = []
    for x in range(sum / / 3 + 1):
    for y in range(x, (sum - x) / / 2 + 1):
    z = sum - x - y
    count = len(p := str(x * y * z)) - len(p . rstrip("0"))
    if count == most:
        res . append([x, y, z])
    elif count > most:
    most = count
    res = [[x, y, z]]
    return res

def find_coords(plane):
