    def spiral(x, y):
    u, v = (x, y) if abs(x) <= abs(y) else (y, x)
    return v * (4 * v - [1, 3][y < x]) + [- u, u][y < x]
    x, y = 0, 0
    visited = set([(x, y)])
    while True:
    ps = [(x + dx, y + dy) for dx, dy in ((- n, - m), (n, - m), (- n, m), (n, m),
                                          (- m, - n), (m, - n), (- m, n), (m, n)) if (x + dx, y + dy) not in visited]
    if not ps:
    return spiral(x, y)
    x, y = min(ps, key=lambda p: spiral(p[0], p[1]))
    visited . add((x, y))

