from typing import Tuple
"""Gets the chord, given the root and color. 
    returns 
    ---------- 
    chord : tuple 
    the chord consisting of its notes -> (C, Eb, G), (F#, A, C#), .. 
    arguments 
    ---------- 
    root : str 
    the root note of the chord -> C, D, F#, Ab, .. 
    color : str 
    the color or type of chord -> m, M, dim, aug 
    """


def chord_triad(root: str, color: str) - > Tuple:
    notes = ('C', 'D', 'E', 'F', 'G', 'A', 'B')
    shifts = ('bb', 'b', '', '#', 'x')

    def is_major(note):
       # checks if the third from the note is major
       # that's true for C, F, and G only
    return note in (0, 3, 4)

    def third_note(note):
    return notes[(note + 2) % len(notes)]

    def minor(note, shift):
    shift -= is_major(note)
    return third_note(note) + shifts[shift]

    def major(note, shift):
    shift += not is_major(note)
    return third_note(note) + shifts[shift]

    triads = {
        'm': (minor, major),
        'M': (major, minor),
        'dim': (minor, minor),
        'aug': (major, major),
    }

    def get_note(root=root):
    note, shift = root[0], root[1:]
    return notes . index(note), shifts . index(shift)

    def get_interval(i, root=root):
    return triads[color][i](* get_note(root))

    third = get_interval(0)
    return (root, third, get_interval(1, third))

CREW = {"F": "Frank", "S": "Sam", "T": "Tom"}
NON_WATER_PROOF = [* CREW, ' ', 'x']


class Flotsam:
    def __init__(self, pic):
    self . pic = pic
    self . sea_level = next(i for i, x in enumerate(pic) if '~' in x)
    self . bottom = len(self . pic)
    self . width = len(self . pic[0])
    self . survivors = dict(* * CREW)

    def show(self):
    print("\n" . join(["" . join(row) for row in self . pic]))

    def drown(self, person):
    name = self . survivors . pop(person)
    print(f" { name } drowned!")

    def leak(self, i1, j1, i2, j2) - > bool:
    a, b = self . pic[i1][j1], self . pic[i2][j2]
    if a == '~' and b in NON_WATER_PROOF:
    if b in self . survivors:
    self . drown(b)
    self . pic[i2][j2] = '~'
    return True
    else:
    return False
    def sink(self):
    leaked = False
    for i in range(self . sea_level, self . bottom):
    for direction in (1, - 1):
    for j in [* range(self . width)][:: direction]:
    if j < self . width - 1:
    leaked |= self . leak(i, j, i, j + 1)
    leaked |= self . leak(i, j + 1, i, j)
    if i > self . sea_level:
    leaked |= self . leak(i, j, i - 1, j)
    if self . sea_level <= i < self . bottom - 1:
    leaked |= self . leak(i, j, i + 1, j)
    self . show()
    if leaked and self . survivors:
    print(self . survivors)
    self . sink()

    def flotsam(pic):
    o = Flotsam(pic)
    o . show()
    o . sink()
    result = " " . join(o . survivors . values())
    return (result)

