from math import comb as nCk, factorial as fac
from itertools import combinations, chain, product


def totally_good(alphabet, bads):

    # starting conditions
    bads = [b for b in bads if not any(o != b and o in b for o in bads)]
    n, t = len(alphabet), fac(len(alphabet))

    # simple edge cases
    if not bads:
        return t
    if any(1 for b in bads if len(b) == 1):
        return 0
    # combinatorics & string patterns
    def count(group, n):
    m, seen, start_cluster = 0, set(), product(
        * [list(range(n - len(b) + 1)) for b in group])
    for start_group in start_cluster:
    word, c = ["*"] * n, False
    for source_idx, target_idx in enumerate(start_group):
    if c:
        break
    b = group[source_idx]
    for i in range(len(b)):
    if word[target_idx + i] != "*" and word[target_idx + i] != b[i]:
    c = True
    break
    word[target_idx + i] = b[i]
    word = '' . join(word)
    if word not in seen and all(e in word for e in group) and len(set([c for c in word if c != '*'])) == len([c for c in word if c != '*']):
    open = word . count("*")
    m += fac(open)
    seen . add(word)
    return m
    # set theory: inclusion/exclusion principle
    history, cluster = {tuple(): t}, list(
        chain(* [combinations(bads, i) for i in range(1, n)]))
    for group in cluster:
    if all(history[subgroup] for subgroup in combinations(group, len(group) - 1)):
    history[group] = count(group, n)
    t += history[group] * (- 1) * * len(group)
    else:
    history[group] = 0
    return t

