def pi_gen(limit):
    q, r, t, k, n, l, cn, d = 1, 0, 1, 1, 3, 3, 0, limit
    while cn != d + 1:
    if 4 * q + r - t < n * t:
    yield n
    if d == cn:
        break
    cn, nr, n, q = cn + 1, 10 * (r - n * t), ((10 * (3 * q + r)) / / t) - 10 * n, q * 10
    r = nr
    else:
    nr, nn, q, t, l, k = (2 * q + r) * l, (q * (7 * k) + 2 + (r * l)) / / (t * l), q * k, t * l, l + 2, k + 1
    n, r = nn, nr
    PI = pi_gen(10000)
    PI = '' . join(map(str, PI))

    def pi(n):
    return int(PI[n])

