def tree_to_prufer(tree):
    res = []
    for _ in range(len(tree) - 2):
    mn = min(k for k, v in tree . items() if len(v) == 1)
    res . append([* tree[mn]][0])
    tree . pop(mn)
    for k, v in tree . items():
    if mn in v:
        v . remove(mn)

    return res
    def prufer_to_tree(prufer_sequence):
    ln, pf = len(prufer_sequence), prufer_sequence[:]
    s = {* range(1, ln + 3)}
    res = {k: set() for k in s}

    for _ in range(ln):
    cur = min(s - set(pf))
    s . remove(cur)
    res[cur]. add(pf[0])
    res[pf . pop(0)]. add(cur)

    a, b = s
    res[a]. add(b)
    res[b]. add(a)

    return res

