    if n == 0:
        return 0, 0, 0, 0
    twos = 1
    while n % 4 == 0:
        n / /= 4
        twos *= 2
    nums = []
    if n % 8 == 7:
    sqrtn = isqrt(n)
    while (n - sqrtn * * 2) % 8 in [0, 4, 7]:
        sqrtn -= 1
    nums . append(sqrtn)
    n -= sqrtn * * 2
    else:
    nums . append(0)
    x = isqrt(n)
    while 1:
    k = n - x * * 2
    k2 = k / / 2 if k % 2 == 0 else k
    if k2 == 1 or (k2 % 4 == 1 and is_prime(k2)):
        break
