    def prime_2sq(p):
    if p == 1:
        return (1, 0)
    if p == 2:
        return (1, 1)
    for q in range(2, p):
    if pow(q, (p - 1) / / 2, p) == p - 1:
        break
    x = pow(q, (p - 1) / / 4, p)
    v = p, x
    rems = []
    sqrtp = isqrt(p)
    while len(rems) < 2:
    if v[1] <= sqrtp:
        rems . append(v[1])
    v = v[1], v[0] % v[1]
    return rems[: 2]
    def compose_2sq(x, y):
    a, b = x
    c, d = y
    return [a * c + b * d, abs(a * d - b * c)]

    def isqrt(n):
    x0 = n / / 2
    if x0:
    x1 = (x0 + n / / x0) / / 2
    while x1 < x0:
    x0 = x1
    x1 = (x0 + n / / x0) / / 2
    return x0
    return n

