def clock(n, xs):
    ks, vs, ptr = [- 1] * n, [0] * n, 0
    def inc():
    nonlocal ptr
    ptr = (ptr + 1) % n
    for x in xs:
    if x in ks:
    vs[ks . index(x)] = 1
    else:
    while vs[ptr]:
    vs[ptr] -= 1
    inc()
    ks[ptr] = x
    inc()
    return ks

