from itertools import combinations


def _add(v0, v1):
    return v0[0] + v1[0], v0[1] + v1[1]

    def _mul(v, k):
    return v[0] * k, v[1] * k
    def _blindfold_chess(moves):
    mcs = {k: [reduce(_add, c) for c in combinations(moves, k)]
           for k in range(1, len(moves) + 1)}
    i = 0
    while mcs:
    i += 1
    for j, ms in reversed(mcs . items()):
    if i % j == 0:
    yield _mul(ms . pop(), i / / j)
    if not ms:
    del mcs[j]
    break
    else:
    yield (0, 0)

    def blindfold_chess(moves):
    return list(_blindfold_chess(moves))

