from functools import cache


def solve(board):
    moves, board = [], board . splitlines()
    poss = {p: i for i, p in enumerate(
        ((x, y) for x, r in enumerate(board) for y, v in enumerate(r) if v != '_'), 1)}

    @ cache
    def dfs(pegs):
    if len(pegs) == 1:
        return True
    for (x, y), m in poss . items():
    if (x, y) not in pegs:
    for dx, dy in ((- 1, 0), (0, - 1), (1, 0), (0, 1)):
    if ((x1 := x + dx), (y1 := y + dy)) in pegs and ((x2 := x + 2 * dx), (y2 := y + 2 * dy)) in pegs:
    moves . append((poss[x2, y2], m))
    if dfs(pegs - frozenset([(x1, y1), (x2, y2)]) | frozenset([(x, y)])):
        return True
    moves . pop()
    return False
    if dfs(frozenset((x, y) for x, y in poss if board[x][y] == 'O')):
        return moves

