from collections import Counter


def closest_string(list_str):
    counters = [Counter(s[i] for s in list_str)
                for i in range(len(list_str[0]))]
    minweight = len(list_str[0]) + 1
    mins = None
    # backtracking with prunning:
    def rec(s, weights):
    nonlocal minweight, mins
    if max(weights) >= minweight:
    return
    if len(s) == len(list_str[0]):
    mins = s
    minweight = max(weights)
    return
    for c in counters[len(s)]. keys():
    rec(s + c, [
        prevw + (c != list_str[i][len(s)])
        for i, prevw in enumerate(weights)
    ])

    rec('', [0] * len(list_str))
    return mins

def score(ball: Ball) - > int:
    res, left, right = ball . point, ball . previous, ball . next
    while left:
    res += left . point
    left = left . previous
    while right:
    res += right . point
    right = right . next
    return res

