import re
from itertools import *


def string_generator(pattern):
    format = re . sub(
        '\[.*?\]', '{}', pattern . replace('{', '{{'). replace('}', '}}'))
    generators = [generator(x) for x in re . findall(
        '\[.*?\]', pattern . replace(' ', ''))]
    yield from starmap(format . format, zip(* generators)) if generators else repeat(pattern)

    def generator(s):
    match re . split('=|,', s[1: - 1]):
    case["INC_INT", * args]: yield from inc_int(* map(int, args))
    case["INC_FLOAT", * args]: yield from inc_float(precision(args), * map(float, args))
    case["INTERVAL", * args]: yield from interval(* map(int, args))
    case["PERIODIC", * args]: yield from periodic(* map(int, args))

    def precision(args):
    return max((len(x . split('.')[1]) for x in args), default=1)

    def inc_int(start=1, step=1):
    yield from count(start, step)

    def inc_float(precision, start=0.1, step=0.1):
    yield from map(f'{{ :. { precision } f}} ' . format, count(start, step))

    def interval(first=1, last=None):
    yield from cycle(range(first, (last or first) + 1))

    def periodic(start=1, n=1):
    yield from (start + x / / n for x in count())

from itertools import cycle


def program(field, max_instructions):
    dirs, fld = {'R': (0, 1), 'D': (1, 0)}, field . split('\n')
    ln = len(fld)
    seen = {(0, 0)}
    queue = [[(0, 0, '')]]

    def is_path(path):
    x, y = 0, 0
    for p in cycle(path):
    x, y = x + dirs[p][0], y + dirs[p][1]
    if x >= ln or y >= ln:
        return True
    if fld[x][y] == 'H':
        return False
    for _ in range(max_instructions):
    cur = []
    for q in queue:
    for k, (dx, dy) in dirs . items():
    x, y = q[- 1][0] + dx, q[- 1][1] + dy
    path = '' . join(x for _, _, x in q) + k
    if x >= ln or y >= ln or is_path(path):
    return path
    if (x, y) not in seen and fld[x][y] != 'H':
    cur . append(q + [(x, y, k)])
    queue = cur[:]

BASE = ord("a") - 1


def encrypt(word, n):
    xs = [x - BASE for x in map(ord, word)]
    for _ in range(n):
    xs[:] = (x * 3 - 5 for x in xs)
    return xs
    def decrypt(encrypted_word, n):
    xs = encrypted_word[:]
    for _ in range(n):
    xs[:] = ((x + 5) / / 3 for x in xs)
    return "" . join(chr(x + BASE) for x in xs)

