def attack_plan(user_count, k):

    dp = [[[- float("inf")] * 4 for _ in range(k + 1)]
          for _ in range(len(user_count) + 1)]  # [time][attacks][consecutive]
    dp[0][0][0] = 0
    for i, count in enumerate(user_count):
    for r in range(k + 1):
    dp[i + 1][r][0] = max(dp[i + 1][r][0], max(dp[i][r]))  # Stop attack
    if r < k:
    dp[i + 1][r + 1][1] = max(dp[i + 1][r + 1][1], dp[i][r][0])
    dp[i + 1][r + 1][2] = max(dp[i + 1][r + 1][2], dp[i][r][1])
    dp[i + 1][r + 1][3] = max(dp[i + 1][r + 1][3],
                              dp[i][r][2] + count, dp[i][r][3] + count)

    return max(dp[- 1][- 1])

