from copy import deepcopy


def decode_smoke_signals(days):
    days = deepcopy(days)
    decoded = {}

    # Keep eliminating signals until the puzzle has been solved
    changed = True
    while changed:
        # Go through day by day and attempt to determine what each signal could be.
    changed = False
    signals = {}
    for day in days:
    for signal in day[0]:
    if not signal in signals:
        # Add all of today's events as possibilities for this signal
    signals[signal] = set([a for a in day[1]])
    else:
        # Remove any previous possibilities that aren't in today's events
    signals[signal] = signals[signal]. intersection(set(day[1]))

    # Add any signals that were solved to the decoded list and remove them
    # from the days list (and up to 1 instance of each corresponding event)
    for signal, possible in signals . items():
    if len(possible) == 1:
    changed = True
    event = list(possible)[0]
    decoded[signal] = event
    for day in days:
    if signal in day[0]:
    day[0]. remove(signal)
    day[1]. remove(event)

    return decoded

