B = [Fraction(1, 1)]
for i in range(1, 141):
    B . append(
        1 - sum(comb(i, j) * Fraction(B[j], i - j + 1) for j in range(i)))

    def build(
        i, x, y): return f" { abs ( x )}{ f'/ { y } ' * ( y > 1 )} n { f'^ { i } ' * ( i > 1 )} "
    fact = lru_cache(maxsize=None)(factorial)

    def equation(k):
    coeff = [build(k + 1, 1, k + 1), '+', build(k, 1, 2)]
    for i in range(2, k + 1):
