def resolver(guess, solution):
    letters, answer = {}, ['b'] * len(guess)
    for i, (g, s) in enumerate(zip(guess, solution)):
    if g == s:
        answer[i] = 'g'
    else:
        letters[s] = letters . get(s, 0) + 1
    for i, (g, s) in enumerate(zip(guess, solution)):
    if g != s and letters . get(g, 0) > 0:
    answer[i] = 'y'
    letters[g] -= 1
    return '' . join(answer)

