def smile(text):
    eyes = [":", ";", "="]
    noses = ["", "-", "~"]
    mouths = ["[", "("]
    mouths_2 = [']', ')']
    for eye in eyes:
    for nose in noses:
    for i, mouth in enumerate(mouths):
    face = eye + nose + mouth
    face_2 = eye + nose + mouths_2[i]
    if face in text:
    text = text . replace(face, face_2)
    return text

import re


def toS(m, s): return f' { m }{ s : 0 > 2 } ' . lstrip('0')


def compact(s): return re . sub(r'(.)\1+', r'\1', s)


def cmpS(a, b): return (len(a) > len(b)) - (len(a) < len(b))


def get_best_combination(t):
    m, s = divmod(t, 60)
    M, S = m - 1, s + 60
    a, b = map(toS, (m, M), (s, S))
    A, B = map(compact, (a, b))
    cmp = cmpS(A, B) or cmpS(a, b)
    return a if s > 39 or cmp < 1 else b

from collections import defaultdict


def neighbors(pos):
    i, j = pos
    return [(i + k, j + l) for k in range(- 1, 2) for l in range(- 1, 2) if k or l]

    def first_impossible(elems) - > int:
    memo, done = defaultdict(int), set(elems)

    def update(p, n):
    for pos in neighbors(p):
    if pos not in done:
    memo[pos] += n
    def rec(n):
    if not (coords := [k for k, v in memo . items() if v == n and k not in done]):
    return n
    res = 0
    for p1 in coords:
    done . add(p1)
    update(p1, n)
    res = max(res, rec(n + 1))
    done . remove(p1)
    update(p1, - n)
    return res
    for p in elems:
    update(p, 1)
    return rec(2)

