def wpp(a, b, n):
    z = []
    for i in range(b):
    c = (a * i) % b
    d = min(c + a, b)
    z . append((a, c))
    z . append((c + a - d, d))
    if n in (c + a - d, d):
        return z
    if c + a >= b:
    z . append((c + a - d, 0))
    z . append((0, c + a - d))
    return []

def fold_cube(nums):
    return expand(nums . pop(), set(nums), 1, 2, 3) == {1, 2, 3, - 1, - 2, - 3}

    def expand(val, nums, x, y, z):
    dirs = {z}
    for num in nums . copy():
    if abs(val - num) not in (1, 5) or {val % 5, num % 5} == {0, 1}:
    continue
    nums . discard(num)
    diff = val - num
    sign = diff / / abs(diff)
    nx, ny, nz = (x, z * sign, - y *
                  sign) if abs(diff) == 1 else (- z * sign, y, x * sign)
    dirs |= expand(num, nums, nx, ny, nz)
    return dirs

