def max_sum_path(a, b):
    i, j, A, B = 0, 0, 0, 0
    while i < len(a) and j < len(b):
    x, y = a[i], b[j]
    if x == y:
        A = B = max(A, B)
    if x <= y:
        i, A = i + 1, A + x
    if x >= y:
        j, B = j + 1, B + y
    return max(A + sum(a[i:]), B + sum(b[j:]))

