def to_mountain(mat):
    h, w = len(mat), len(mat[0])
    for j in range(h):
    for i in range(w):
    if j:
        mat[j][i] = max(mat[j][i], mat[j - 1][i] - 1)
    if i:
        mat[j][i] = max(mat[j][i], mat[j][i - 1] - 1)
    if j and i:
        mat[j][i] = max(mat[j][i], mat[j - 1][i - 1] - 1)
    if j and i + 1 < w:
        mat[j][i] = max(mat[j][i], mat[j - 1][i + 1] - 1)
    if j + 1 < h and i:
        mat[j][i] = max(mat[j][i], mat[j + 1][i - 1] - 1)
    for j in reversed(range(h)):
    for i in reversed(range(w)):
    if j + 1 < h:
        mat[j][i] = max(mat[j][i], mat[j + 1][i] - 1)
    if i + 1 < w:
        mat[j][i] = max(mat[j][i], mat[j][i + 1] - 1)
    if j + 1 < h and i + 1 < w:
        mat[j][i] = max(mat[j][i], mat[j + 1][i + 1] - 1)
    if j and i + 1 < w:
        mat[j][i] = max(mat[j][i], mat[j - 1][i + 1] - 1)
    if j + 1 < h and i:
        mat[j][i] = max(mat[j][i], mat[j + 1][i - 1] - 1)
    return mat

