def gen(l, p, arr, n, q):
    if not p:
        yield []
        return
    for i in p:
    if len(l) + 1 < n or sum(l[len(l) - n + 1:]) + arr[i] <= q:
    for s in gen(l + [arr[i]], p - set([i]), arr, n, q):
        yield [arr[i]] + s

