def get_minimum_hamiltonian_cycle(adj):
    candidates = [((a,), 0) for a in adj]
    best_cycle = None
    best_cost = float('inf')
    len_adj = len(adj)
    while candidates:
    path, cost = candidates . pop()
    for node, c in adj[path[- 1]]. items():
    new_cost = cost + c
    if node not in path:
    if new_cost < best_cost:
    candidates . append(((* path, node), new_cost))
    elif node == path[0] and len(path) == len_adj and new_cost < best_cost:
    best_cycle = path
    best_cost = new_cost
    return best_cycle

