def array_erasing(lst):
    # coding and coding...
    dic = []
    last = lst[0]
    count = 0
    for i, j in enumerate(lst):
    if j == last:
    count += 1
    else:
    dic . append(count)
    last = j
    count = 1
    dic . append(count)
    step = 0
    length = len(dic)
    p1 = (length - 1) / / 2
    p2 = length / / 2
    while True:
    if len(dic) > 4:
    if dic[p1] > 1 or dic[p2] > 1:
    return step + ceil((length + 1) / 2)
    if dic[p1 - 1] > 1:
    step += 1
    dic[p1 - 2] += dic[p1]
    dic . pop(p1 - 1)
    dic . pop(p1 - 1)
    length = len(dic)
    p1 = (length - 1) / / 2
    p2 = length / / 2
    continue
    if dic[p2 + 1] > 1:
    step += 1
    dic[p2] += dic[p2 + 2]
    dic . pop(p2 + 1)
    dic . pop(p2 + 1)
    length = len(dic)
    p1 = (length - 1) / / 2
    p2 = length / / 2
    continue
    if p1 >= 2 and p2 <= len(dic) - 4:
    p1 -= 1
    p2 += 1
    elif len(dic) <= 4:
    continue
    else:
    if dic[0] + dic[- 1] > 2:
    return step + ceil(len(dic) / 2) + 1
    else:
    return step + ceil((len(dic) + 1) / 2)

    else:
    length = len(dic)
    if length == 4:
    if dic[1] + dic[2] == 2 and dic[0] + dic[3] >= 4:
    return step + 4
    else:
    return step + 3
    elif length == 3:
    if dic[1] == 1 and dic[0] + dic[2] >= 3:
    return step + 3
    else:
    return step + 2
    else:
    return len(dic)

def three_split(arr):
    need = sum(arr) / 3
    result, chunks, current = 0, 0, 0
    for i in range(0, len(arr) - 1):
    current += arr[i]
    if current == 2 * need:
    result += chunks
    if current == need:
    chunks += 1
    return result

