def dots_and_boxes(moves):
    nodes = 1 + max(chain . from_iterable(moves))
    player, Y = 0, int(nodes * * .5)
    pts, grid = [0, 0], [4] * nodes
    for a, b in moves:
    swap = 1
    if a > b:
        a, b = b, a
    for i in (a, a - Y if b - a == 1 else a - 1):
    if i < 0:
        continue
    grid[i] -= 1
    if not grid[i]:
    pts[player] += 1
    swap = 0
    player ^= swap
    return tuple(pts)

