    fct = find_factors(n)

    tot, cur, stot, sarr = int(len(fct) > 0), {tuple(fct)}, 0, []
    if s == len(fct):
    stot, sarr = tot, fct
    for k in range(len(fct) - 2):
    cset = set()
    for t in cur:
