    for j, y in enumerate(t[i + 1:], i + 1):
    cset . add(
        tuple(sorted(t[: i] + t[i + 1: j] + t[j + 1:] + (t[i] * t[j],))))
    cur = cset
    tot += len(cur)
    if k == len(fct) - s - 1:
