>>> radixTree("ape", "apple")
{ ap: { e: {}, ple: {} } }

>>> radixTree("apple", "applet", "apple", "ape")
{ ap: { ple: { t: {} }, e: {} } }

>>> radixTree("romane", "romanus", "romulus", "rubens", "rubicon", "rubicundus")
{ r: { om: { an: { e: {}, us: {} }, ulus: {} }
     , ub: { ens: {}, ic: { on: {}, undus: {} } }
}    }
```
