    e = int(log10(bill))
    unit = (10 * * e) / 2
    return ceil(bill / unit) * unit

def relations(family_list, target_pair):
    parents = {}
    for parent, child in family_list:
    parents[child] = parent
    a, b = target_pair
    ap = parents . get(a)
    app = parents . get(ap)
    bp = parents . get(b)
    bpp = parents . get(bp)

    if b == ap:
    return 'Mother'
    if b == app:
    return 'Grandmother'
    if a == bp:
    return 'Daughter'
    if a == bpp:
    return 'Granddaughter'
    if ap == bp:
    return 'Sister'
    if app == bpp:
    return 'Cousin'
    if app == bp:
    return 'Aunt'
    if ap == bpp:
    return 'Niece'

def reflections(n, m):
    x = y = 0
    dx = dy = 1
    while 1:
    x += dx
    y += dy
    if x == y == 0 or x == n and y == m:
        return 1
    if 0 in (x, y) and (x == n or y == m):
        return 0
    if x in (0, n):
        dx *= - 1
    if y in (0, m):
        dy *= - 1

