    if what and not ret:
        FATAL(f'Expected { what } but got { ret } (i= { i } )')
    walk(1)
    return CONVERTER . get(ret, ret)

    def taste(what=None):
    return i < len (tokens) and (what is None or re . match (what , tokens [i ])) and tokens [i ]

    # -----------------------------------------------------

    def _type():
    if taste(r'\('):
        return _functionType()
    elif not taste(NAME):
        FATAL(f"Expected a name but got { taste ()} ")
    name = eat()
    if taste('[<.]'):
        return _userType(name)
    else:
        return name

    def _functionType():
    eat()
    params = []
    if not taste(r'\)'):
    while 1:
    params . append(_type())
    if taste(r'\)'):
        break
    eat(',')
    eat(r'\)')
    eat("->")
    params . append(_type())

    return f'Function { len ( params ) - 1 } < { "," . join ( params ) } >'
    def _userType(name):
    userT = name
    if taste('<'):
        userT += _typeParams()
    if taste(r'\.'):
        userT += eat (r'\.') + _userType (eat (NAME ))
    return userT
    def _typeParams():
    lst = []
    eat('<')
    while 1:
    lst . append(_typeParam())
    if not taste(','):
        break
    eat()
    eat('>')
    return f"< { ',' . join ( lst ) } >"
    def _typeParam():
    if taste(r'\*|in |out '):
    x = eat()
    if x != '?':
        x += eat(NAME)
    return x
    else:
    return _type()

    # -----------------------------------------------------
    i, tokens = 0, TOKENIZER . findall(s)
    try:
    walk()
    ans = _type()
    if i == len(tokens):
        return ans
    except InvalidExpr as e:
        pass

