def find_cycle(a, b):
    if (a % 2 and b % 2) or 1 in {a, b}:
    return None
    else:
    r, c = (a, b) if a % 2 == 0 else (b, a)
    res = [(0, y) for y in range(c)]
    res . extend([(x, c - 1) for x in range(1, r)])

    for k, x in enumerate(range(r - 1, 0, - 1)):
    res . extend([(x, y if k % 2 else c - 2 - y) for y in range(c - 1)])
    res . append((0, 0))

    return res if r == a else [(y, x) for x, y in res]

