def f(d_max, n):
    """Calculate the nth element of 
    d_max-th Farey sequence in descending order."""
    a, b, c, d = 1, 1, d_max - 1, d_max
    for _ in range(n):
    if a == 0:
        break
    k = (d_max + b) / / d
    a, b, c, d = c, d, (k * c - a), (k * d - b)
    return f" { a } / { b } " if a else "-1"

