    def parse(time):
    hours, minutes, seconds, milliseconds = map(
        int, time . replace(',', ':'). split(':'))
    return ((hours * 60 + minutes) * 60 + seconds) * 1000 + milliseconds
    def render(time, min=parse('00:00:00,000'), max=parse('99:59:59,999')):
    if not min <= time <= max:
    raise OverflowError
    seconds, milliseconds = divmod(time, 1000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    return f' { hours :0 2 } : { minutes :0 2 } : { seconds :0 2 } , { milliseconds :0 3 } '
    try:
    start, _, stop, * text = subs . split()
    start, stop = parse(start), parse(stop)
    return f' { render ( start + offset )} --> { render ( stop + offset )} { " " . join ( text )} '
    except OverflowError:
    return 'Invalid offset'

