    S = A + C
    if N < 0:  # elliptic
    if M == 0:
        return 'A degenerated ellipse: One point'
    if M * S < 0:
        return 'A real ellipse'
    if M * S > 0:
        return 'An imaginary ellipse'
    if N > 0:  # hyperbolic
    if M == 0:
        return 'A degenerated hyperbola: two intersecting lines'
    if M != 0:
        return 'A real hyperbola'
    if N == 0:  # parabolic
    if M != 0:
        return 'A real parabola'
    delta = D * * 2 - 4 * A * F
    if delta == 0:
