    distance_p_center = np . sqrt(y_movement * * 2 + x_movement * * 2)
    distance_to_cross = distance_p_center * radius / np . sqrt(quotients[0] * * 2 * x_movement * * 2 + quotients[1] * * 2 * y_movement * * 2)
