    self . rollback()
    self . updatePlayer()  # Restore current player if invalid move
    raise ValueError(msg)

    def handicap_stones(self, n):
    if self . hasHandi or self . archive or self . p:
        raise ValueError("No, I wont...")
    self . hasHandi = True
    # raise an exception if invalid size of the board
    pos = iter(self . HANDICAP[(self . lenX, self . lenY)])
    for _ in range(n):
        # raise an exception of too many number of handicap stones asked for
    x, y = self . pos[next(pos)]
    self . board[x][y] = self . SYMBOLS[self . p]

    def move(self, * moves):

    for m in moves:

    self . archive . append(deepcopy(self . board))  # Archive for rollback
    x, y = self . pos . get(m, (- 1, - 1))
    if (x, y) == (- 1, - 1) or self . board[x][y] != '.':
    self . rollInvalidMove_Raise(["Reproduction of stones does not work... (at {})" . format(m),
                                  "Play in the board, damn you!!"][(x, y) == (- 1, - 1)])

    # Retrieve player and opponent symbols
    player, opp = self . SYMBOLS[::(- 1) * * (2 * * self . p ^ 1)]
    self . board[x][y] = player  # Update the board
    around = [(x + dx, y + dy) for dx, dy in self . MOVES
              if 0 <= x + dx < self . lenX and 0 <= y + dy < self . lenY
              and self . board[x + dx][y + dy] != '.']

    # {"x": list of tuples [(set of (x,y), liberty count), ...], "o": ...}
    grpsAround = {player: [], opp: []}
    for a, b in around + [(x, y)]:  # Extract all the groups (opponent AND player) around the concerned position: (sets of positions, liberties count), as many lists of tuples that there are groups of stones
    c = self . board[a][b]
    # Update the groups and lib value only if the current seed position is not already in a previously found group
    if not any((a, b) in neighGrp for neighGrp in grpsAround[c]):
    grpsAround[c]. append(self . floodLib(a, b, c))

    isSuicidal = grpsAround[player][0][1] == 0
    isCapturing = any(lib == 0 for _, lib in grpsAround[opp])
    if isSuicidal and not isCapturing:  # Forbid self-capturing (suicide)
    self . rollInvalidMove_Raise("You definitely have suicidal tendances")

    for grp, lib in grpsAround[opp]:
    if lib == 0:  # Handle captures of opponent's stones
    for a, b in grp:
        self . board[a][b] = '.'  # Remove opponent's stone
    # Check for KO rule
    if len(grp) == 1 and len(self . archive) > 2 and self . board == self . archive[- 2]:
    self . rollInvalidMove_Raise("You're knocked out! Again!")

    self . updatePlayer()  # Change the current player
    def floodLib(self, x, y, c):  # Floof-fill the board, retrieving all the pieces of the same group and counting its liberties at the same time
    pos = (x, y)
    seens, q, grp, lib = {pos}, {pos}, {pos}, 0
    while q:
    x, y = q . pop()
    for dx, dy in self . MOVES:
    a, b = pos = x + dx, y + dy
    if 0 <= a < self . lenX and 0 <= b < self . lenY and pos not in seens:
    if self . board[a][b] == '.':
        lib += 1
    elif self . board[a][b] == c:
        grp . add(pos)
        q . add(pos)
    seens . add(pos)
    return grp, lib

import re


def calc_poly(coefs, x):
    coefs = coefs[:: - 1]
    res = sum(x * * i * c for i, c in enumerate(coefs))
    poly = ' + ' . join(["{}*x^{}" . format(c, i)
                        for i, c in enumerate(coefs) if c][:: - 1])
    poly = re . sub(r'\*x\^0|\^1\b|\b1\*(?!x\^0)',
                    '', poly). replace("+ -", "- ")
    return "For {} with x = {} the value is {}" . format(poly, x, res)

import re


class RSUProgram:

    ID_PATT_BRA = r'[PpRFL)](?:0|[1-9]\d*)|[RFLq()]'
    WHITE_COMMENTS = r'\s+|//.*?(?:\n|$)|/\*.*?\*/'
    TOKENIZER = re . compile(r'|' . join(
        [WHITE_COMMENTS, ID_PATT_BRA, r'.']), flags=re . DOTALL)
    VALID_TOKEN = re . compile(ID_PATT_BRA)
    IS_NOT_TOKEN = re . compile(WHITE_COMMENTS, flags=re . DOTALL)
    MOVES = ((0, 1), (1, 0), (0, - 1), (- 1, 0))

    def __init__(self, prog): self . source = prog

    def convert_to_raw(self, tokens): return [
        c for c, r in self . compileCode(tokens) for _ in range(r)]
    def execute(self): return self . execute_raw(
        '', self . compileCode(self . get_tokens()))

    def compileCode(self, tokens):
    scope = {'parent': None, 'cmd': ()}
    return self . applyPatterns(self . parseCode(iter(tokens), scope), scope, 0)

    def get_tokens(self):
    tokens = []
    for tok in self . TOKENIZER . findall(self . source):
    if self . IS_NOT_TOKEN . match(tok):
        continue
    elif self . VALID_TOKEN . match(tok):
        tokens . append(tok)
    elif tok:
        raise Exception("Invalid expression found: {}" . format(tok))
    return tokens
    def execute_raw(self, cmds, todo=None):
    pos, seens, iDir = (0, 0), {(0, 0)}, 0
    # OVERRIDE todo/cmds TO BYPASS SPECIFICATIONS...
    for s, r in todo or ((c, 1) for c in cmds):
    if s == 'F':
    for _ in range(r):
    pos = tuple(z + dz for z, dz in zip(pos, self . MOVES[iDir]))
    seens . add(pos)
    else:
    iDir = (iDir + r * (- 1) * * (s == 'L')) % len(self . MOVES)

    miX, maX = (f(x for x, _ in seens) for f in (min, max))
    miY, maY = (f(y for _, y in seens) for f in (min, max))

    return '\r\n' . join('' . join('*' if (x, y) in seens else ' ' for y in range(miY, maY + 1))
                         for x in range(miX, maX + 1))

    def parseCode(self, tokIter, scope, inPattern=0):
    cmds = [[]]
    for tok in tokIter:
    cmd, r = tok[0], int(tok[1:] or '1')
    isRepeat = cmds[- 1] and cmds[- 1][- 1] and cmds[- 1][- 1][0] == cmd
    if cmd in 'pq' and len(cmds) > 1:
        raise Exception("pattern definition inside brackets")

    if cmd == 'p':
    name = tok . upper()
    if name in scope:
        raise Exception("Invalid pattern: cannot define multiple patterns with the same name at the same level: {}\nScope: {}\n\n{}" . format(
            name, scope, self . source))
    else:
    freshScope = {'parent': scope, 'cmds': ()}
    scope[name] = freshScope
    freshScope['cmds'] = self . parseCode(tokIter, freshScope, 1)

    elif cmd == 'q':
    if not inPattern:
        raise Exception('unopened pattern definition')
    inPattern = 0
    break
    elif cmd == '(':
        cmds . append([])
    elif cmd == ')':
        lst = cmds . pop()
        cmds[- 1]. extend(lst * r)
    elif isRepeat:
        cmds[- 1][- 1] = (cmd, cmds[- 1][- 1][1] + r)
    else:
        cmds[- 1]. append((tok, 1) if cmd == 'P' else (cmd, r))

    if inPattern:
        raise Exception("unclosed pattern definition, last token: " + tok)
    if len(cmds) > 1:
        raise Exception("unclosed brackets, last token: " + tok)
    return cmds[0]

    def applyPatterns(self, rawCmds, scope, depth):
    if depth == 20:
        raise Exception("Stack overflow")
    lst = []
    for c, r in rawCmds:
    if c[0] != 'P':
        lst . append((c, r))
    else:
    pattern, nextScope = self . reachPattern(scope, c)
    lst . extend(self . applyPatterns(pattern, nextScope, depth + 1))
    return lst
    def reachPattern(self, scope, name):
    calledP = scope . get(name)
    parent = scope['parent']
    if calledP is not None:
        return calledP['cmds'], calledP
    if not parent:
        raise Exception("Unknown pattern: " + name)
    return self . reachPattern(parent, name)

