from math import log


def phi(n):
    r, i = n, 2
    while i * i <= n:
    if n % i == 0:
    r = r / / i * (i - 1)
    while n % i == 0:
        n / /= i
    i += 1
    if n > 1:
        r = r / / n * (n - 1)
    return r
    def _tower(base, h, m):
    if h < 2 or m == 1:
        return pow(base, h, m)
    p = phi(m)
    return pow(base, p + tower(base, h - 1, p), m)

    def tower(base, h, m):
    res = 1
    for _ in range(h):
    if res * log(base) > log(m):
        return _tower(base, h, m)
    res = base * * res
    return res % m

def traffic_jam(road, sides):
