def dithering(width, height):
    size = 1
    while width > size or height > size:
    size *= 2
    if size == 1:
    yield (0, 0)
    else:
    for (x, y) in dithering(size / 2, size / 2):
    for t in ((x, y), (x + size / 2, y + size / 2), (x + size / 2, y), (x, y + size / 2)):
    if t[0] < width and t[1] < height:
    yield t

import re


def atm(value):
    match = re . fullmatch('([A-Z]+) ?(\d+)|(\d+) ?([A-Z]+)', value . upper())
    currency = match . group(1) or match . group(4)
    value = int(match . group(2) or match . group(3))
    if currency not in VALUES:
    return "Sorry, have no {}." . format(currency)
    if value % VALUES[currency][0]:
    return "Can't do {} {}. Value must be divisible by {}!" . format(value, currency, VALUES[currency][0])
    result = []
    for v in VALUES[currency][:: - 1]:
    if value and v <= value:
    result . append("{} * {} {}" . format(value / / v, v, currency))
    value %= v
    return ", " . join(result)

