    st = iter(text . split())
    cur = next(st, None)

    res = ['']
    while cur:
    if len(res[- 1]) + len(cur) + (res[- 1] != '') <= limit:
    res[- 1] += ' ' * (res[- 1] != '') + cur
    cur = next(st, None)
    elif len(cur) > limit and limit - len(res[- 1]) - 1 > 0:
    ind = limit - len(res[- 1]) - (res[- 1] != '')
