def reverse_fizzbuzz(s):
    if s == 'Fizz':
        return [3]
    if s == 'Buzz':
        return [5]
    if s == 'Fizz Buzz':
        return [9, 10]
    if s == 'Buzz Fizz':
        return [5, 6]
    if s == 'FizzBuzz':
        return [15]
    s = s . split()
    for i in range(len(s)):
    if s[i]. isdigit():
    start = int(s[i]) - i
    return list(range(start, start + len(s)))

def peak(arr):
    for i, val in enumerate(arr):
    if sum(arr[: i]) == sum(arr[i + 1:]):
    return i
    return - 1

def hop_across(lst):
    def one_side(lst):
    i = 0
    steps = 0
    while i < len(lst):
    i += lst[i]
    steps += 1
    return steps
    return one_side(lst) + one_side(lst[:: - 1])

def solve(arr, reach):
    dogs, nCats = {i for i, x in enumerate(arr) if x == 'D'}, 0
    for i, c in enumerate(arr):
    if c == 'C':
    catchingDog = next(
        (i + id for id in range(- reach, reach + 1) if i + id in dogs), None)
    if catchingDog is not None:
    nCats += 1
    dogs . remove(catchingDog)
    return nCats

def bit_letter(n):
    def code(n):
    x, i = divmod(n, 32)
    p, c = divmod(x, 2)
    return ' ' * (p == 1) + chr(97 + i - c * 32) + ',.' [p - 2] * (p > 1)
    return '' . join(code(i) for i in n)

def Zeckendorf_rep(n):
    if n >= 0:
    fibs, res = [1, 2], []

    while fibs[- 1] < n:
    fibs . append(sum(fibs[- 2:]))

    while n > 0:
    x = fibs . pop()
    if x <= n:
    res . append(x)
    n -= x
    return res

