def putTheCatOnTheTable(cat, map):
    lX, lY = len(map), len(map[0])
    x, y = cat
    if not (0 <= x < lX and 0 <= y < lY):
        return 'NoCat'
    try:
    table = divmod(list(chain . from_iterable(map)). index(1), lY)
    except ValueError:
    return "NoTable"
    return '' . join(['UD', 'LR'][i][d > 0] * abs(d) for i, d in enumerate([b - a for a, b in zip(cat, table)]))

# Top portion is adapted from my solution for a different kata about this language
