from enum import Enum
D = Enum('Direction', ['U', 'D', 'L', 'R'])


def interpret(code):
    instructions = tuple(l for l in code . split('\n'))
    output = ""
    ip = [0, 0]
    direction = D . R
    op = instructions[ip[1]][ip[0]]
    stack = []
    def pop(): return stack . pop() if stack else 0
    def div(a, b): return b / / a if a != 0 else 0
    def mod(a, b): return b % a if a != 0 else 0
    def sub(a, b): return b - a
    while op != '@':
    if op == '^':
        direction = D . U
    elif op == '<':
        direction = D . L
    elif op == '>':
        direction = D . R
    elif op == 'v':
        direction = D . D
    elif op == '|':
        direction = D . U if pop() else D . D
    elif op == ':':
        stack . append(stack[- 1] if stack else 0)
    elif op == '$':
        pop()
    elif op == '.':
        output += str(pop())
    elif op == ',':
        output += chr(pop())
    elif op == ' ':
        pass
    elif op == '+':
        stack . append(pop() + pop())
    elif op == '-':
        stack . append(sub(pop(), pop()))
    elif op == '*':
        stack . append(pop() * pop())
    elif op == '/':
        stack . append(div(pop(), pop()))
    elif op == '%':
        stack . append(mod(pop(), pop()))
    elif op . isdigit():
        stack . append(int(op))

    # Move to next instruction
    if direction == D . L:
        ip[0] = (ip[0] - 1) % len(instructions[ip[1]])
    elif direction == D . R:
        ip[0] = (ip[0] + 1) % len(instructions[ip[1]])
    elif direction == D . U:
        ip[1] = (ip[1] - 1) % len(instructions)
    elif direction == D . D:
        ip[1] = (ip[1] + 1) % len(instructions)
    op = instructions[ip[1]][ip[0]]

    return output
    def podium_code():
    return interpret(':345**/.87vv98,:<>\nv/*52:,+2*<>**- |\n>6%.:52*%.1+:25*^@')

