import re
from abc import ABC
from collections import ChainMap
from collections.abc import Iterable, Iterator, MutableMapping
from contextlib import AbstractContextManager
from dataclasses import asdict, dataclass, fields, replace
from enum import Enum
from itertools import islice, tee
from typing import Any, Literal, overload


# I try to be pedantic and avoid undefined behaviour,
# so I also raise this in all cases that are said to be never tested.
# Except for division by zero and out-of-bound lset/lget,
# which are impossible to check at compile time.
class KcufError(Exception):
    '''Any possible error in the program source code.'''
    pass


# -----------------------------------------------------------------------------
#                                   Lexer
#
#                Splits the source code into a stream of tokens.
#        Works like a filter, doesn't hold more than 1 token in memory.
# -----------------------------------------------------------------------------

_CHAR_ELEMENT_PATTERN = r'''(?:[^'"\n\\]|[\\][\\'"nrt])'''


class TokenType(Enum):
    COMMENT       = r'(?:^[ \t]*[Rr][Ee][Mm]\b|//|--|#).*?$'
    VAR_NAME      = r'[A-Za-z$_][A-Za-z$_0-9]*'
    BRACKET       = r'[\[\]]'
    NUMBER        = r'-?[0-9]+'
    CHAR          = f"'{_CHAR_ELEMENT_PATTERN}'"
    STRING        = f'"{_CHAR_ELEMENT_PATTERN}*"'
    EOL           = r'\n'
    WHITESPACE    = r'[ \t]+'
    INVALID_TOKEN = r'.'

    def __repr__(self) -> str:
        return f'{self.__class__.__name__}.{self.name}'


TT = TokenType
_TOKEN_PATTERN = '|'.join(f'({t.value})' for t in TokenType)
_TOKEN = re.compile(_TOKEN_PATTERN, re.MULTILINE)


@dataclass(repr=False)
class Token:
    type: TokenType
    value: str

    def __repr__(self) -> str:
        return f'{type(self).__name__}({self.type.name}, {repr(self.value)})'


def _primary_lex(source: str) -> Iterator[Token]:
    '''Just split `source` into tokens defined in `TOKEN_CLASSES`.'''
    for match in _TOKEN.finditer(source):
        matched_group = match.lastindex
        assert matched_group is not None, 'Some group should always match'
        token_type = list(TokenType)[matched_group - 1]
        token_value = match[matched_group]
        yield Token(token_type, token_value)


def lex(source: str) -> Iterator[Token]:
    '''Split `source` into tokens which are useful for the parser.'''
    tokens = _primary_lex(source)
    for token in tokens:
        if token.type == TT.INVALID_TOKEN:
            # Apart from unclosed strings/chars,
            # this also covers other random gibberish that's never tested.
            raise KcufError('Invalid token')
        if token.type in (TT.WHITESPACE, TT.COMMENT):
            continue
        yield token


# -----------------------------------------------------------------------------
#                                   Parser
#
#                      Combines tokens into statements,
#                 verifies the grammar for blocks and procs.
#
#     Works like a filter, doesn't hold more than 1 statement in memory.
# -----------------------------------------------------------------------------


def _iter_line(tokens: Iterable[Token]) -> Iterator[Token]:
    '''Iterate over `tokens` until EOL of EOF.'''
    for token in tokens:
        if token.type == TT.EOL:
            break
        yield token


class String(str):
    '''A string literal in the program.'''

    def __repr__(self) -> str:
        return f'{type(self).__name__}({super().__str__()})'


class VarName(str):
    '''A simple implementation of a case-insensitive string.
    Represents a variable/list/procedure/parameter name.
    '''

    def __new__(cls, contents: str):
        if isinstance(contents, VarName):
            contents = contents._contents  # type:ignore
        self = str.__new__(cls, contents.casefold())
        self._contents = contents  # type:ignore
        return self

    def __repr__(self) -> str:
        return f'{type(self).__name__}({repr(self._contents)})'  # type:ignore


class ListName(VarName):
    pass


@dataclass
class Constant:
    value: int


VarNameOrNumber = VarName | Constant


def _parse_var_name(token: Token) -> VarName:
    if token.type != TT.VAR_NAME:
        raise KcufError('Expect a variable but got something else')
    return VarName(token.value)


def _parse_var_name_or_number(token: Token) -> VarNameOrNumber:
    match token:
        case Token(TT.VAR_NAME, name):
            return VarName(name)
        case Token(TT.NUMBER, value_str):
            value = int(value_str) % 256
            return Constant(value)
        case Token(TT.CHAR, value_str):
            value = ord(eval(value_str))
            return Constant(value)
        case _:
            # This case is never tested.
            raise KcufError('Expect VarNameOrNumber but got something else')


@dataclass
class Declaration:
    name: VarName
    size: int | None = None

    @property
    def is_list(self) -> bool:
        return self.size is not None


class Statement(ABC):
    '''Abstract base class for all statements.'''

    @classmethod
    def parse(cls, args: Iterable[Token]) -> 'Statement':
        # Default implementation that works for all fixed-size instructions.
        try:
            return cls(*cls._parse_fields(args))
        except ValueError:
            raise KcufError('Number of arguments for an instruction '
                            'does not match the expectation')

    @classmethod
    def _parse_fields(cls, args: Iterable[Token]) -> Iterator[Any]:
        '''Parse own fields from tokens (`cls` must be a dataclass).'''
        args = _iter_line(args)
        for field, token in zip(fields(cls), args, strict=True):
            if field.type is VarNameOrNumber:
                yield _parse_var_name_or_number(token)
            elif field.type is VarName:
                yield _parse_var_name(token)
            elif field.type is ListName:
                yield ListName(_parse_var_name(token))
            else:
                assert False, 'Forgot to add case'


@dataclass
class Var(Statement):
    declarations: list[Declaration]

    @classmethod
    def parse(cls, args: Iterable[Token]) -> 'Var':
        declarations = list(cls._parse_declarations(args))
        if len(declarations) == 0:
            raise KcufError('Number of arguments for an instruction '
                            'does not match the expectation')
        return Var(declarations)

    @staticmethod
    def _parse_declarations(tokens: Iterable[Token]) -> Iterator[Declaration]:
        tokens = _iter_line(tokens)
        # We need to see 4 tokens ahead.
        window = list(islice(tokens, 4))
        # Window becomes empty after we've consumed all tokens.
        while window:
            match window:
                case [Token(TT.VAR_NAME, name), Token(TT.BRACKET, '['),
                      Token(TT.NUMBER, size_str), Token(TT.BRACKET, ']')]:
                    n_consumed = 4
                    size = int(size_str)
                    if not 1 <= size <= 256:
                        # This case is never tested.
                        raise KcufError('List size must be in range [1,256]')
                    yield Declaration(ListName(name), size)
                case [Token(TT.VAR_NAME, name), *_]:
                    n_consumed = 1
                    yield Declaration(VarName(name))
                case _:
                    # This covers 'Unclosed [] pair'
                    # and other random gibberish that's never tested.
                    raise KcufError('Expect VarSingle but got something else')
            # Move the window forward.
            window = window[n_consumed:] + list(islice(tokens, n_consumed))


@dataclass
class Set(Statement):
    a: VarName
    b: VarNameOrNumber


@dataclass
class Inc(Statement):
    a: VarName
    b: VarNameOrNumber


@dataclass
class Dec(Statement):
