@dataclass
class Proc(Statement):
    name: VarName
    params: list[VarName]

    @classmethod
    def parse(cls, args: Iterable[Token]) -> 'Proc':
        args_iter = _iter_line(args)
        name_arg = next(args_iter, None)
        if name_arg is None:
            raise KcufError('Number of arguments for an instruction '
                            'does not match the expectation')
        name = _parse_var_name(name_arg)
        params = [_parse_var_name(a) for a in args_iter]
        return Proc(name, params)


@dataclass
class End(Statement):
    pass


@dataclass
class Call(Statement):
    proc_name: VarName
    arguments: list[VarName]

    @classmethod
    def parse(cls, args: Iterable[Token]) -> 'Call':
        args_iter = _iter_line(args)
        name_arg = next(args_iter, None)
        if name_arg is None:
            raise KcufError('Number of arguments for an instruction '
                            'does not match the expectation')
        proc_name = _parse_var_name(name_arg)
        proc_args = [_parse_var_name(a) for a in args_iter]
        return Call(proc_name, proc_args)


@dataclass
class Read(Statement):
    var_name: VarName


@dataclass
class Msg(Statement):
    args: list[VarName | String]

    @classmethod
    def parse(cls, args: Iterable[Token]) -> 'Msg':
        msg_args = [cls._parse_var_name_or_string(a) for a in _iter_line(args)]
        if len(msg_args) == 0:
            raise KcufError('Number of arguments for an instruction '
                            'does not match the expectation')
        return Msg(msg_args)

    @staticmethod
    def _parse_var_name_or_string(token: Token) -> VarName | String:
        match token.type:
            case TT.STRING:
                return String(token.value)
            case TT.VAR_NAME:
                return VarName(token.value)
            case _:
                # This case is never tested.
                raise KcufError('Expect VarNameOrString but got somethin else')


@dataclass
class Rem(Statement):
    pass


def _is_concrete_statement_type(cls: type) -> bool:
    return issubclass(cls, Statement) and cls is not Statement


def _parse_statements(tokens: Iterable[Token]) -> Iterator[Statement]:
    # A sentinel value that's never seen in the actual lexer output.
    eof = Token(TT.COMMENT, 'EOF')

    tokens_iter = iter(tokens)
    for token in tokens_iter:
        # Skip empty lines.
        while token.type == TT.EOL:
            token = next(tokens_iter, eof)
        if token is eof:
            break

        statement_cls_name = token.value.capitalize()
        statement_cls = globals_().get(statement_cls_name, None)
        if not _is_concrete_statement_type(statement_cls):
            # This also covers non-VarName tokens, which are never tested.
            raise KcufError('Unknown instructions')
        yield statement_cls.parse(tokens_iter)


def _check_block_grammar(program: Iterable[Statement]) -> Iterator[Statement]:
    unclosed_proc = False
    unclosed_blocks = 0
    for statement in program:
        match statement:
            case Var() if unclosed_proc:
                raise KcufError('Define variables inside a procedure')
            case Proc() if unclosed_proc:
                raise KcufError('Nested procedures')
            case Proc():
                unclosed_proc = True
            case Ifeq() | Ifneq() | Wneq():
                unclosed_blocks += 1
            case End() if unclosed_blocks:
                unclosed_blocks -= 1
            case End() if unclosed_proc:
                unclosed_proc = False
            case End():
                raise KcufError('End before beginning a block')
        yield statement
    if unclosed_blocks or unclosed_proc:
        raise KcufError('Unclosed blocks')


def parse(tokens: Iterable[Token]) -> Iterator[Statement]:
    '''Check for grammatical errors and combine tokens into statements.'''
    statements = _parse_statements(tokens)
    return _check_block_grammar(statements)


# -----------------------------------------------------------------------------
#                                Preprocessor
#
#                         Checks for semantic errors,
#              removes proc definitions and inlines proc calls.
# -----------------------------------------------------------------------------


@dataclass
class _Procedure():
    name: VarName
    params: list[VarName]
    body: list[Statement]


class _Lookup:
    '''A lookup table for variables and procedures.'''

    def __init__(self) -> None:
        self._variables = ChainMap[VarName, Declaration]()
        self._procedures = dict[VarName, _Procedure]()
        self._call_stack = list[VarName]()

    @property
    def _globals(self) -> MutableMapping[VarName, Declaration]:
        return self._variables.maps[-1]

    def add_global(self, var: Declaration) -> None:
        if var.name in self._globals:
            raise KcufError('Duplicate var names')
        self._globals[var.name] = var

    def add_procedure(self, procedure: _Procedure) -> None:
        if procedure.name in self._procedures:
            raise KcufError('Duplicate procedure names')
        if len(set(procedure.params)) < len(procedure.params):
            raise KcufError('Duplicate parameter names')
        self._procedures[procedure.name] = procedure

    def new_scope(self, proc: _Procedure, arguments: list[VarName]
                  ) -> AbstractContextManager:
        '''Return a context manager that allows to
        enter and exit the scope of a procedure, affecting lookup.
        '''
        class ContextManager:
            def __enter__(self_) -> 'ContextManager':
                if proc.name in self._call_stack:
                    raise KcufError('Recursive call')
                self._call_stack.append(proc.name)
                if len(arguments) != len(proc.params):
                    raise KcufError('The length of arguments does not match '
                                    'the length of parameters')
                resolved_args = [self.var(name) for name in arguments]
                bindings = {p: a for p, a in zip(proc.params, resolved_args)}
                self._variables.maps.insert(0, bindings)  # type:ignore
                return self_

            def __exit__(self_, exc_type, exc_value, exc_traceback) -> None:
                self._call_stack.pop()
                self._variables.maps.pop(0)

        return ContextManager()

    def proc(self, proc_name: VarName) -> _Procedure:
        try:
            return self._procedures[proc_name]
        except KeyError:
            raise KcufError('Undefined procedure')

    def var(self, var_name: VarName) -> Declaration:
        var = self._var_or_list(var_name)
        if var.is_list:
            raise KcufError('Expect a variable but got a list')
        return var

    def list(self, name: ListName) -> Declaration:
        var = self._var_or_list(name)
        if not var.is_list:
            raise KcufError('Expect a list but got a variable')
        return var

    def _var_or_list(self, var_name: VarName) -> Declaration:
        if var_name not in self._variables:
            # This also covers variables used before they are defined,
            # which currently isn't tested.
            raise KcufError('Undefined var names')
        return self._variables[var_name]


def _iter_until_matching_end(body: Iterable[Statement]) -> Iterator[Statement]:
    unclosed_blocks = 1
    for statement in body:
        if isinstance(statement, (Ifeq, Ifneq, Wneq)):
            unclosed_blocks += 1
        elif isinstance(statement, End):
            unclosed_blocks -= 1
            if not unclosed_blocks:
                break
        yield statement


class _Preprocessor:
    def __init__(self) -> None:
        self._lookup: _Lookup
        self._unused_procs: set[VarName]

    def preprocess(self, program: Iterable[Statement]) -> Iterator[Statement]:
        self._lookup = _Lookup()
        self._unused_procs = set[VarName]()
        # Make a full pass to register procs and remove definitions from main.
        main = list(self._remove_procs(program))
        # Then work on a stream.
        return self._expand_main(main)

    def _remove_procs(self, body: Iterable[Statement]) -> Iterator[Statement]:
        body_iter = iter(body)
        for statement in body_iter:
            if isinstance(statement, Proc):
                proc_body = list(_iter_until_matching_end(body_iter))
                proc = _Procedure(statement.name, statement.params, proc_body)
                self._lookup.add_procedure(proc)
                self._unused_procs.add(proc.name)
            else:
                yield statement

    def _expand_main(self, main: Iterable[Statement]) -> Iterator[Statement]:
        yield from self._expand_calls(main)
        if self._unused_procs:
            # This case is never tested.
            raise KcufError('Unused procedures')

    def _expand_calls(self, body: Iterable[Statement]) -> Iterator[Statement]:
        for statement in body:
            if isinstance(statement, Var):
                for decl in statement.declarations:
                    self._lookup.add_global(decl)
                yield statement
            elif isinstance(statement, Call):
                procedure = self._lookup.proc(statement.proc_name)
                with self._lookup.new_scope(procedure, statement.arguments):
                    yield from self._expand_calls(procedure.body)
                self._unused_procs.discard(procedure.name)
            else:
                statement = self._resolve_var_names(statement)
                yield statement

    def _resolve_var_names(self, statement: Statement) -> Statement:
        '''Resolve used parameters (if any) to the gloval vars they point to'''
        match statement:
            case Msg(args):
                # A special case because fields aren't scalar.
                resolved_args = list(self._resolve_msg_args(args))
                return Msg(resolved_args)
            case _:
                fields_dict = asdict(statement)
                updated_fields = {
                    fn: self._resolve_name(fv)
                    for fn, fv in fields_dict.items()
                    if isinstance(fv, VarName)
                }
                return replace(statement, **updated_fields)

    def _resolve_msg_args(self, args: Iterable[VarName | String]
                          ) -> Iterator[VarName | String]:
        for arg in args:
            if isinstance(arg, VarName):
                yield self._resolve_name(arg)
            else:
                yield arg

    def _resolve_name(self, name: VarName) -> VarName:
        '''If `name` refers to a parameter, resolve it
        to the gloval variable that it points to.
        '''
        if isinstance(name, ListName):
            referenced_list = self._lookup.list(name)
            return referenced_list.name
        else:
            referenced_var = self._lookup.var(name)
            return referenced_var.name


def preprocess(program: Iterable[Statement]) -> Iterator[Statement]:
    '''Check for semantic errors, remove proc definitions and inline calls.'''
    return _Preprocessor().preprocess(program)


# -----------------------------------------------------------------------------
#                                 Backend
#
#     Takes a valid program from the previous step and translates it to BF.
# -----------------------------------------------------------------------------


@dataclass
class _Variable:
    address: int


@dataclass
class _List:
    HEAD_SIZE = 4

    address: int
    size: int


_Rvalue = _Variable | Constant


@dataclass(init=False)
class _Zeroed:
    '''A marker for `_Backend._free()` arguments.
    Indicates that the cleanup is not needed.
    '''

    address: int

    def __init__(self, var: _Variable) -> None:
        self.address = var.address


@dataclass
class _IfBlock:
    cond_var: _Variable


@dataclass
class _WhileBlock:
    a: _Rvalue
    b: _Rvalue
    cond_var: _Variable


_Block = _IfBlock | _WhileBlock


class _Backend:
    '''Generates BF code, statement by statement.'''

    # The main idea is to treat the cell array like a stack.
    # Statements are implemented using algorithms that claim
    # available cells at the top, use them, and then reset them back to 0.

    # Common principles for private methods:
    # - Translate the eponymous concept into BF.
    # - Write the result into `_buffer` attribute.
    # - Don't clobber variables that are supposed to be read-only.
    #     (But sometimes, `consume` option is available. When set to `True`,
    #      it produces more optimized BF code and sets the variable to 0.)
    # - Always handle cases where multiple operands alias the same cell.
    #     Don't push responsibility onto the caller.
    # - Apply constant folding where it's easy to implement.

    def __init__(self, *, cleanup_blocks: bool) -> None:
        '''`cleanup_blocks=False` allows to compile everything in one pass,
        but this approach leaks one cell per each `ifeq/ifneq/wneq` block,
        producing a bloated cell layout that's hard to understand and debug.

        `cleanup_blocks=True` fixes the leak, but one-pass compilation
        crashes if there are any `vars` defined inside of blocks.
        That's because everything is stack allocated and these `vars`
        are allocated on top of the block cell that needs to be cleaned up.

        My preferred approach is using `cleanup_blocks=True` with two passes:
        pre-allocating all `vars` in advance and then generating the code.
        '''
        self._cleanup_blocks = cleanup_blocks

        self._buffer = list[str]()
        '''Generated BF code goes here.'''

        self._ptr = 0
        '''Points at the current data cell.'''

        self._stack_ptr = 0
        '''Points at the first available cell on the "BF stack".
        This cell and all cells to the right are always zeroed.'''

        self._blocks = list[_Block]()
        '''A stack to keep track of of entered ifeq,ifneq,wneq blocks.'''

        self._vars = dict[VarName, _Variable]()
        self._lists = dict[VarName, _List]()

    def get_full_result(self) -> str:
        '''Return full contents of the internal buffer.'''
        return ''.join(self._buffer)

    def generate(self, statement: Statement) -> None:
        '''Translate statement to BF code and append it to internal buffer.'''
        args = self._lookup_args(statement)
        match statement:
            case Var():     self._var(*args)
            case Set():     self._set(*args)
            case Inc():     self._inc(*args)
            case Dec():     self._dec(*args)
            case Add():     self._add(*args)
            case Sub():     self._sub(*args)
            case Mul():     self._mul(*args)
            case Divmod():  self._divmod(*args)
            case Div():     self._div(*args)
            case Mod():     self._mod(*args)
            case Cmp():     self._cmp(*args)
            case A2b():     self._a2b(*args)
            case B2a():     self._b2a(*args)
            case Lset():    self._lset(*args)
            case Lget():    self._lget(*args)
            case Ifeq():    self._ifeq(*args)
            case Ifneq():   self._ifneq(*args)
            case Wneq():    self._wneq(*args)
            case Proc():    assert False, 'Should be already removed'
            case End():     self._end(*args)
            case Call():    assert False, 'Should be already expanded'
            case Read():    self._read(*args)
            case Msg():     self._msg(*args)
            case Rem():     pass
            case _:         assert False, 'Forgot to add case'

    def _lookup_args(self, statement: Statement) -> Iterator[Any]:
        '''Iterate `statement` args, translating variable names to addresses'''
        args: Iterable[Any]
        args = (getattr(statement, field.name) for field in fields(statement))
        # Special cases when statement fields are not scalar.
        if isinstance(statement, Var):
            args = statement.declarations
        elif isinstance(statement, Msg):
            args = statement.args
        for arg in args:
            match arg:
                case ListName() as list_name:
                    yield self._lists[list_name]
                case VarName() as var_name:
                    yield self._vars[var_name]
                case _:
                    yield arg

    def _var(self, *declarations: Declaration) -> None:
        for decl in declarations:
            if decl.is_list:
                assert decl.size is not None, 'Lists are always sized'
                self._lists[decl.name] = self._allocate_list(decl.size)
            else:
                self._vars[decl.name] = self._allocate_var()

    def _set(self, dest: _Variable, source: _Rvalue, *, consume=False) -> None:
        if isinstance(source, _Variable) and source.address == dest.address:
            return
        self._append(dest, '[-]')
        self._inc(dest, source, consume=consume)

    def _inc(self, dest: _Variable, source: _Rvalue, *, consume=False) -> None:
        if isinstance(source, _Variable) and source.address == dest.address:
            copy = self._allocate_copy(source)
            self._inc_dec_impl('inc', dest, copy, consume=True)
            self._free(_Zeroed(copy))
            return
        self._inc_dec_impl('inc', dest, source, consume=consume)

    def _dec(self, dest: _Variable, source: _Rvalue, *, consume=False) -> None:
        if isinstance(source, _Variable) and source.address == dest.address:
            self._append(dest, '[-]')
            return
        self._inc_dec_impl('dec', dest, source, consume=consume)

    def _inc_dec_impl(self, instruction: Literal['inc', 'dec'],
                      dest: _Variable, source: _Rvalue, *, consume=False
                      ) -> None:
        '''Assumes `source.address != dest.address`!'''
        op = '+' if instruction == 'inc' else '-'
        match source:
            case _Variable() if consume:
                self._append(source, '[', dest, op, source, '-]')
            case _Variable():
                temp = self._allocate_var()
                self._append(source, '[', dest, op, temp, '+', source, '-]')
                self._append(temp, '[', source, '+', temp, '-]')
                self._free(_Zeroed(temp))
            case Constant():
                self._append(dest, op * source.value)

    def _add(self, op1: _Rvalue, op2: _Rvalue, dest: _Variable) -> None:
        self._set(dest, op1)
        self._inc(dest, op2)

    def _sub(self, op1: _Rvalue, op2: _Rvalue, dest: _Variable) -> None:
        self._set(dest, op1)
        self._dec(dest, op2)

    def _mul(self, mul1: _Rvalue, mul2: _Rvalue, dest: _Variable) -> None:
        self._set(dest, mul1)
        # Now we can do `dest *= mul2`:
        temp = self._allocate_var()
        self._inc(temp, dest, consume=True)
        self._append(temp, '[')
        self._inc(dest, mul2)
        self._append(temp, '-]')
        self._free(_Zeroed(temp))

    def _divmod(self, a: _Rvalue, b: _Rvalue,
                c: _Variable, d: _Variable) -> None:
        self._divmod_div_mod_impl('divmod', a, b, c, d)

    def _div(self, a: _Rvalue, b: _Rvalue, c: _Variable) -> None:
        self._divmod_div_mod_impl('div', a, b, c)

    def _mod(self, a: _Rvalue, b: _Rvalue, c: _Variable) -> None:
        self._divmod_div_mod_impl('mod', a, b, c)

    def _divmod_div_mod_impl(self,
                             instruction: Literal['divmod', 'div', 'mod'],
                             a: _Rvalue, b: _Rvalue, c: _Variable,
                             d: _Variable | None = None) -> None:
        # Harcoded algorithm requires x,y,r,q on the top of the stack.
        x = self._allocate_copy(a)
        y = self._allocate_copy(b)
        r = self._allocate_var()
        q = self._allocate_var()
        self._append(
            x, '[->[->+>>]>[<<+>>[-<+>]>+>>]<<<<<]>[>>>]>[[-<+>]>+>>]<<<<<'
        )
        match instruction:
            case 'div':
                self._set(c, q, consume=True)
                self._free(_Zeroed(q), r, y, _Zeroed(x))
            case 'mod':
                self._set(c, r, consume=True)
                self._free(q, _Zeroed(r), y, _Zeroed(x))
            case 'divmod':
                assert d is not None, "'divmod' requires d"
                self._set(c, q, consume=True)
                self._set(d, r, consume=True)
                self._free(_Zeroed(q), _Zeroed(r), y, _Zeroed(x))

    def _cmp(self, x: _Rvalue, y: _Rvalue, dest: _Variable) -> None:
        # Easy optimization if `x` and `y` are the same constant or cell.
        if x == y:
            self._set(dest, Constant(0))
            return

        is_not_equal = self._allocate_var()
        self._not_equals(x, y, is_not_equal)
        # Pure speculation.
        self._set(dest, Constant(0))
        # If x != y, this branch will execute and set `dest` to 1 or 255.
        self._append(is_not_equal, '[')
        self._cmp_not_equal(x, y, dest)
        self._append(is_not_equal, '-]')
        self._free(_Zeroed(is_not_equal))

    def _not_equals(self, x: _Rvalue, y: _Rvalue, dest: _Variable) -> None:
        '''If `x` != `y`, set `dest` to 1. Else, set `dest` to 0.'''
        # Easy optimization if `x` and `y` are the same constant or cell.
        if x == y:
            self._set(dest, Constant(0))
            return

        # The algorithm below writes the result to `x`,
        # so we put `x` in `dest` and use `dest` instead.
        self._set(dest, x)
        # It also needs `y` as a Variable and zeroes it, so we make a copy.
        # Copy will also protect us if the original `y` aliases `dest`.
        y = self._allocate_copy(y)

        diff = self._allocate_var()
        self._inc(diff, dest, consume=True)
        self._dec(diff, y, consume=True)
        self._append(diff, '[', dest, '+', diff, '[-]]')
        self._free(_Zeroed(diff), _Zeroed(y))

    def _cmp_not_equal(self, x: _Rvalue, y: _Rvalue, dest: _Variable) -> None:
        '''Assumes `x` != `y` and `dest` == 0. Sets `dest` to 255 or 1.'''
        # The algorithm below writes the result to `x`,
        # so we need to protect the original.
        x = self._allocate_copy(x)
        # Algorithm for `x = x < y`:
        temp0 = self._allocate_var()
        temp1 = self._allocate_var()
        temp2 = self._allocate_var()  # In the algrorithm, these are unnamed.
        temp3 = self._allocate_var()  # But they need to be cleaned up.
        self._append(temp1, '>+<')
        self._set(temp1, y)
        self._append(x, '[', temp0, '+', x, '-]+')
        self._append(temp1, '[>-]> [<', x, '-', temp0, '[-]', temp1, '>->]<+<')
        self._append(temp0, '[', temp1, '-[>-]>')
        self._append('[<', x, '-', temp0, '[-]+', temp1, '>->]')
        self._append('<+<', temp0, '-]')
        self._free(temp3, temp2, temp1, _Zeroed(temp0))
        # Speculatively set `dest` from 0 to 1, assuming that `x > y`.
        self._append(dest, '+')
        # If `x < y`, execute the branch that sets `dest` from 1 to 255.
        self._append(x, '[', dest, '--', x, '-]')
        self._free(_Zeroed(x))

    def _a2b(self, a: _Rvalue, b: _Rvalue, c: _Rvalue, d: _Variable) -> None:
        term = self._allocate_var()
        with self._temporary(d) as d:
            self._sub(a, Constant(48), term)
            self._mul(term, Constant(100), d)
            self._sub(b, Constant(48), term)
            self._mul(term, Constant(10), term)
            self._inc(d, term, consume=True)
            self._sub(c, Constant(48), term)
            self._inc(d, term, consume=True)
        self._free(_Zeroed(term))

    def _b2a(self, a: _Rvalue, b: _Variable,
             c: _Variable, d: _Variable) -> None:
        with self._temporary(b, c, d) as (b, c, d):
            self._div(a, Constant(100), b)
            self._inc(b, Constant(48))
            self._div(a, Constant(10), c)
            self._mod(c, Constant(10), c)
            self._inc(c, Constant(48))
            self._mod(a, Constant(10), d)
            self._inc(d, Constant(48))

    @overload
    def _temporary(self, v: _Variable, /) -> AbstractContextManager[_Variable]:
        ...

    @overload
    def _temporary(self, v0: _Variable, v1: _Variable, /, *vn: _Variable,
                   ) -> AbstractContextManager[tuple[_Variable, ...]]:
        ...

    def _temporary(self, *vars: _Variable) -> AbstractContextManager:
        '''Upon entering, return temporaries to be used instead of `vars`.

        Upon exiting, write back to `vars` (in the order listed)
        and destroy temporaries.

        This protects any variables aliased by `vars`
        from being overwritten before exiting the context.
        '''
        class ContextManager:
            def __enter__(self_) -> _Variable | tuple[_Variable, ...]:
                self_._temps = tuple(self._allocate_var() for _ in vars)
                if len(self_._temps) == 1:
                    return self_._temps[0]
                return self_._temps

            def __exit__(self_, exc_type, exc_value, exc_traceback) -> None:
                temps_and_originals = list(zip(self_._temps, vars))
                for temp, original in temps_and_originals:
                    self._set(original, temp, consume=True)
                # Need to free stack allocated memory in reverse order.
                for temp, original in reversed(temps_and_originals):
                    self._free(_Zeroed(temp))

        return ContextManager()

    def _lset(self, a: _List, b: _Rvalue, c: _Rvalue) -> None:
        if isinstance(b, Constant):
            cell_in_list = self._const_index(a, b)
            self._set(cell_in_list, c)
            return
        space = _Variable(a.address)
        index1 = _Variable(a.address + 1)
        index2 = _Variable(a.address + 2)
        data = _Variable(a.address + 3)
        self._set(data, c)
        self._set(index1, b)
        self._set(index2, b)
        # lset from `data`:
        self._append(space, '>[>>>[-<<<<+>>>>]<[->+<]<[->+<]<[->+<]>-]')
        self._append('>>>[-]<[->+<]<')
        self._append('[[-<+>]<<<[->>>>+<<<<]>>-]<<')

    def _lget(self, a: _List, b: _Rvalue, c: _Variable) -> None:
        if isinstance(b, Constant):
            cell_in_list = self._const_index(a, b)
            self._set(c, cell_in_list)
            return
        space = _Variable(a.address)
        index1 = _Variable(a.address + 1)
        index2 = _Variable(a.address + 2)
        data = _Variable(a.address + 3)
        self._set(index1, b)
        self._set(index2, b)
        # lget into `data`:
        self._append(space, '>[>>>[-<<<<+>>>>]<<[->+<]<[->+<]>-]')
        self._append('>>>[-<+<<+>>>]<<<[->>>+<<<]>')
        self._append('[[-<+>]>[-<+>]<<<<[->>>>+<<<<]>>-]<<')
        # Now we only need to:
        self._set(c, data, consume=True)

    def _const_index(self, list: _List, index: Constant) -> _Variable:
        '''Get address of a list cell at compile time.'''
        if not 0 <= index.value < list.size:
            # This case is never tested.
            raise KcufError('Out of bounds list access')
        return _Variable(list.address + _List.HEAD_SIZE + index.value)

    def _ifeq(self, a: _Variable, b: _Rvalue) -> None:
        self._ifeq_ifneq_impl('ifeq', a, b)

    def _ifneq(self, a: _Variable, b: _Rvalue) -> None:
        self._ifeq_ifneq_impl('ifneq', a, b)

    def _ifeq_ifneq_impl(self, statement: Literal['ifeq', 'ifneq'],
                         a: _Variable, b: _Rvalue) -> None:
        cond_var = self._allocate_var()  # Freed after the end of the block.
        self._not_equals(a, b, cond_var)
        if statement == 'ifeq':
            self._unary_not(cond_var)
        self._append(cond_var, '[-')
        block = _IfBlock(cond_var)
        self._blocks.append(block)

    def _unary_not(self, x: _Variable) -> None:
        '''If `x` == 0, set `x` to 1. Else, set `x` to 0.'''
        temp = self._allocate_var()
        self._append(x, '[', temp, '+', x, '[-]]+')
        self._append(temp, '[', x, '-', temp, '-]')
        self._free(_Zeroed(temp))

    def _wneq(self, a: _Variable, b: _Rvalue) -> None:
        cond_var = self._allocate_var()  # Freed after the end of the block.
        self._not_equals(a, b, cond_var)
        self._append(cond_var, '[')
        block = _WhileBlock(a, b, cond_var)
        self._blocks.append(block)

    def _end(self) -> None:
        block = self._blocks.pop()
        if isinstance(block, _WhileBlock):
            self._not_equals(block.a, block.b, block.cond_var)
        self._append(block.cond_var, ']')
        if self._cleanup_blocks:
            self._free(_Zeroed(block.cond_var))

    def _read(self, var: _Variable) -> None:
        self._append(var, ',')

    def _msg(self, *args: _Variable | String) -> None:
        for argument in args:
            match argument:
                case _Variable() as var:
                    self._append(var, '.')
                case String() as string:
                    self._print_string(string)

    def _print_string(self, string: String) -> None:
        '''Generate hardcode for printing a string constant.'''
        self._goto(self._stack_ptr)
        for byte_value in eval(string).encode():
            self._append('+' * byte_value, '.[-]')

    def _free(self, *variables: _Variable | _Zeroed) -> None:
        for var in variables:
            if not isinstance(var, _Zeroed):
                self._append(var, '[-]')
            assert var.address == self._stack_ptr - 1, 'Invalid deallocation'
            self._stack_ptr -= 1

    def _allocate_copy(self, rv: _Rvalue) -> _Variable:
        copy = self._allocate_var()
        self._set(copy, rv)
        return copy

    def _allocate_list(self, size: int) -> _List:
        address = self._allocate_stack(size + _List.HEAD_SIZE)
        return _List(address, size)

    def _allocate_var(self) -> _Variable:
        address = self._allocate_stack()
        return _Variable(address)

    def _allocate_stack(self, size: int = 1) -> int:
        pre_increment = self._stack_ptr
        self._stack_ptr += size
        return pre_increment

    def _append(self, *args: str | _Variable) -> None:
        '''For each argument:
        * If `str`: treat it as BF code and append to the `_buffer` as is.
        * If `Variable`: generate a jump to that variable.

        This allows for a nice notation like the followng:
        ```
        A: Variable = ...
        B: Variable = ...
        self._append(A, '[-]', B, '[-]')  # set A and B to 0
        ```
        '''
        for arg in args:
            if isinstance(arg, _Variable):
                self._goto(arg.address)
            else:
                self._buffer.append(arg)

    def _goto(self, addr: int) -> None:
        '''Generate a jump to the given cell.'''
        offset = addr - self._ptr
        if offset > 0:
            self._buffer.append('>' * offset)
        elif offset < 0:
            self._buffer.append('<' * abs(offset))
        self._ptr = addr


def generate_bf(program: Iterable[Statement]) -> str:
    '''Translate a valid preprocessed `program` to BF.'''
    # It's possible to compile everything in one pass:

    # backend = _Backend(cleanup_blocks=False)
    # for statement in program:
    #     backend.generate(statement)
    # return backend.get_full_result()

    # But I prefer this approach:

    backend = _Backend(cleanup_blocks=True)
    pass1, pass2 = tee(program)
    # Pre-allocate globals.
    for statement in pass1:
        if isinstance(statement, Var):
            backend.generate(statement)
    # Generate the other instructions.
    for statement in pass2:
        if not isinstance(statement, Var):
            backend.generate(statement)
    return backend.get_full_result()


# -----------------------------------------------------------------------------
#                                Transpiler
#
#              High-level pipeline of the other components.
# -----------------------------------------------------------------------------


def kcuf(code: str) -> str:
    tokens = lex(code)
    program = parse(tokens)
    program = preprocess(program)
    return generate_bf(program)


