                 for i in range(1, 10)] + [str(i) + 'z' for i in range(1, 8)]
    for new_tile in [x for x in all_tiles if x]:
    new_hand = [new_tile] + tile_list
    counts = [(x, new_hand . count(x)) for x in set(new_hand)]

    if new_tile in [x[0] for x in counts if x[1] == 5]:
