import math


def bocce_score(balls):
    xy = balls[- 1]['distance']
    balls = balls[: - 1]
    for b in balls:
    b['distance'] = math . sqrt(((xy[0] - b['distance'][0]) * * 2) + ((xy[1] - b['distance'][1]) * * 2))
    reds = [x for x in balls if x['type'] == "red"]
    blacks = [x for x in balls if x['type'] == "black"]
    red = min(reds, key=lambda x: x['distance'])['distance']
    black = min(blacks, key=lambda x: x['distance'])['distance']

    if black == red:
    return "No points scored"
    elif black < red:
    return "black scores %d" % len([x for x in blacks if x['distance'] < red])
    else:
    return "red scores %d" % len([x for x in reds if x['distance'] < black])

