    if (prime_factors_length(i) == k and prime_factors_length(i + step) == k):
    res . append([i, i + step])
    return res

def king_move_combo(ar):
    n = len(ar)
    field = list(map(list, ar))
    def max_move(x0, y0):
    mm = 0
    for dx, dy in ((- 1, - 1), (- 1, 1), (1, 1), (1, - 1)):
    x, y = x0 + 2 * dx, y0 + 2 * dy
    if x >= 0 and x < n and y >= 0 and y < n:
    xe, ye = x0 + dx, y0 + dy
    if field[xe][ye] == 'X':
    field[xe][ye] = ' '
    m = max_move(x, y) + 1
    if m > mm:
    mm = m
    field[xe][ye] = 'X'
    return mm
    return max_move(* next((x, y) for x, r in enumerate(field) for y, c in enumerate(r) if c == 'K'))

import numpy as np


def slope(p1, p2):
    dx, dy = vectorize(p1, p2)
    return dy / dx if dx else float("inf")

    def vectorize(p1, p2): return [b - a for a, b in zip(p1, p2)]
    def getArea(p1, p2, p3): return np . cross(
        vectorize(p1, p2), vectorize(p1, p3)) / 2

    def isConcave(p1, pivot, p2): return getArea(pivot, p1, p2) >= 0
    def convex_hull_area(points):
    if len(points) < 3:
        return 0
    # Leftmost point in the graph (lowest if several ones at the same x)
    Z = min(points)
    q = sorted((pt for pt in points if pt != Z),
               key=lambda pt: (- slope(pt, Z), - np . linalg . norm(vectorize(Z, pt))))  # sorted points accordingly to the slope of the line formed by "pt" and "Z" (in reversed order)
    hull = [Z, q . pop()]  # Construct the convex hull (Graham Scan)
    while q:
    pt = q . pop()
    while len(hull) > 1 and isConcave(hull[- 2], hull[- 1], pt):
    hull . pop()
    hull . append(pt)

    # Calculate area of the hull by adding the area of all the triangles formed by 2 consecutive points in the hull and having Z as summit
    area = sum(getArea(Z, hull[i], hull[i + 1])
               for i in range(1, len(hull) - 1))
    return round(area, 2)

def hull_method(points):
    sorted_points = sorted(points)
    return half_hull(sorted_points) + half_hull(reversed(sorted_points))

    def half_hull(sorted_points):
    hull = []
    for p in sorted_points:
    while len(hull) > 1 and not is_ccw_turn(hull[- 2], hull[- 1], p):
    hull . pop()
    hull . append(p)
    hull . pop()
    return hull
    def is_ccw_turn(p0, p1, p2):
    return (p1[0] - p0[0]) * (p2[1] - p0[1]) - (p2[0] - p0[0]) * (p1[1] - p0[1]) > 0

