def number_to_english(n):
    z = '''zero one two three four five six seven eight nine ten eleven twelve 
 thirteen fourteen fifteen sixteen seventeen eighteen nineteen'''
    D = {i: w for i, w in enumerate(z . split())}
    for i, w in enumerate('twenty thirty forty fifty sixty seventy eighty ninety' . split(), 2):
        D[i * 10] = w
    if not isinstance(n, int) or not (0 <= n <= 99999):
        return ''
    d, r = divmod(n, 1000)
    s = [number_to_english(d), 'thousand'] if d else []
    d, r = divmod(r, 100)
    if d:
        s += [number_to_english(d), 'hundred']
    if r and r in D:
        s, r = s + [D[r]], 0
    d, r = divmod(r, 10)
    s += ([number_to_english(d * 10)] if d else []) + \
        ([number_to_english(r)] if r else [])
    return ' ' . join(s) if s else D[0]

