def angle_planes(lstPts):
    vectPlans = [np . cross(np . subtract(p1, p2), np . subtract(p1, p3))
                 for p1, p2, p3 in [lstPts[: 3], lstPts[3:]]]
    n1, n2, vp = map(np . linalg . norm, vectPlans + [np . cross(* vectPlans)])
