    x, y = min(bag, key=bag . get)
    rounds = bag . pop((x, y))
    seen . add((x, y))
    if (x, y) == end:
        return rounds
    for u, v in (- 1, 0), (0, 1), (1, 0), (0, - 1):
    m, n = x + u, y + v
