def check_pipe(pipe_map):
    def get(y, x): return pipe_map[y][x] if 0 <= y < len(
        pipe_map) and 0 <= x < len(pipe_map[0]) else None
    UP, LEFT, DOWN, RIGHT = (- 1, 0), (0, - 1), (1, 0), (0, 1)
    pipes = {
        '┗': (UP, RIGHT),
        '┓': (LEFT, DOWN),
        '┏': (RIGHT, DOWN),
        '┛': (UP, LEFT),
        '━': (LEFT, RIGHT),
        '┃': (UP, DOWN),
        '┣': (UP, DOWN, RIGHT),
        '┫': (UP, DOWN, LEFT),
        '┳': (LEFT, DOWN, RIGHT),
        '┻': (LEFT, UP, RIGHT),
        '╋': (UP, LEFT, RIGHT, DOWN)
    }
    ok = set()
    to_check = {(y, x) for y, r in enumerate(pipe_map)
                for x, v in enumerate(r)
                if (y == 0 or y == len(pipe_map) - 1 or x == 0 or x == len(pipe_map[0]) - 1)
                and get(y, x) != '.'
                and any(get(y + dy, x + dx) is None for dy, dx in pipes[v])
                }
    while to_check:
    y, x = to_check . pop()
    for dy, dx in pipes[get(y, x)]:
    if (v := get(y + dy, x + dx)) is None:
    continue
    if v == '.' or (- dy, - dx) not in pipes[v]:
    return False
    ok . add((y, x))
    if (y + dy, x + dx) not in ok:
    to_check . add((y + dy, x + dx))
    return True

