class Colors (Enum):
    White = 0
    Black = 1
    class Entry:

    @ staticmethod
    def parse(amount, index):
    return Entry(amount, Colors((index % 2) ^ 1))

    def __init__(self, amount, color):
    self . amount = amount
    self . color = color
    def take(self, amount):
    amount = min(amount, self . amount)
    self . amount -= amount
    return amount
    def is_empty(self):
    return not self . amount
    def __repr__(self):
    return f"( { self . amount } , { self . color } )"
    class Bag:

    @ staticmethod
    def parse(compressed):
    return Bag([Entry . parse(e, i) for i, e in enumerate(compressed)][:: - 1])

    def __init__(self, data):
    self . data = data
    def take(self, amount, color):
    if self . is_empty():
    return 0
    current = self . peek()
    if color != current . color:
    return 0
    amount = current . take(amount)
    if current . is_empty():
    self . data . pop()
    return amount
    def peek(self):
    return 0 if self . is_empty() else self . data[- 1]

    def is_empty(self):
    return not len(self . data)

    def __repr__(self):
    return repr(self . peek())

    def black_and_white(height, width, compressed):
    bag, res = Bag . parse(compressed), []
    while not bag . is_empty():
    row, remaining = [], width
    while remaining:
    amount_black = bag . take(remaining, Colors . Black)
    row . append(amount_black)
    remaining -= amount_black
    amount_white = bag . take(remaining, Colors . White)
    row . append(amount_white)
    remaining -= amount_white
    res . append(row)
    return res

