def sec_deg_solver(a, b, c):
    if a:
    delta = b * b - 4 * a * c
    if delta < 0:
    msg = MSG[4]
    elif delta > 0:
    roots = round((- b - sqrt(delta)) / (2 * a),
                  10), round((- b + sqrt(delta)) / (2 * a), 10)
    msg = MSG[6]. format(* sorted(roots))
    else:
    root = round(- b / (2 * a), 10)
    msg = MSG[5]. format(root)
    else:
    if b:
    if c:
    root = round(- c / b, 10)
    msg = MSG[0]. format(root)
    else:
    msg = MSG[3]
    else:
    if c:
    msg = MSG[2]
    else:
    msg = MSG[1]
    return msg

