def show(digits, size):
    line = ' ' + '-' * size + ' '
    space = ' ' * (size + 2)
    l_sp = '|' + ' ' * (size + 1)
    sp_r = ' ' * (size + 1) + '|'
    l__r = '|' + ' ' * size + '|'
    level_1 = {str(k): space if str(k) in '14' else line for k in range(10)}
    level_2 = {str(k): sp_r if str(k) in '1237' else l_sp if str(
        k) in '56' else l__r for k in range(10)}
    level_3 = {str(k): space if str(k) in '170' else line for k in range(10)}
    level_4 = {str(k): sp_r if str(k) in '134579' else l_sp if str(
        k) in '2' else l__r for k in range(10)}
    level_5 = {str(k): space if str(k) in '147' else line for k in range(10)}

    ans = '' . join([level_1[i] for i in digits]) + '\n' + \
        ('' . join([level_2[i] for i in digits]) + '\n') * size + \
        '' . join([level_3[i] for i in digits]) + '\n' + \
        ('' . join([level_4[i] for i in digits]) + '\n') * size + \
        '' . join([level_5[i] for i in digits])

    while ' \n' in ans:
        ans = ans . replace(' \n', '\n')
    while ans[- 1] == ' ':
        ans = ans[: - 1]
    return ans

