def ds_multof_pfs(a, b):
    return [n for n in range(a, b + 1) if divisor_sum(n) % prime_factor_sum(n) == 0]

    def divisor_sum(n, p=2, s=0):
    s += 1 + (0 if n == 1 else n)
    while p * p <= n:
    if n % p == 0:
    s += p
    if n / / p != p:
    s += n / / p
    p += 1
    return s
    def prime_factor_sum(n, p=2, s=0):
    while p * p <= n:
    while n % p == 0:
    n / /= p
    s += p
    p += 1
    if n > 1:
    s += n
    return s

