def get_number_of_reachable_fields(grid, rows, columns, start_row, start_column):
    reachable, bag, seen = 0, [(start_row, start_column)], {
        (start_row, start_column)}
    while bag:
    x, y = bag . pop()
    reachable += x == rows - 1
    for u, v in (1, 0), (0, 1), (0, - 1):
    m, n = x + u, y + v
    if 0 <= m < rows and 0 <= n < columns \
            and (m, n) not in seen and grid[m][n]:
    bag . append((m, n))
    seen . add((m, n))
    return reachable

