def count_find_num(primesL, limit):
    base_num = reduce((lambda a, b: a * b), primesL, 1)
    if base_num > limit:
    return []
    nums = [base_num]
    for i in primesL:
    for n in nums:
    num = n * i
    while (num <= limit) and (num not in nums):
    nums . append(num)
    num *= i
    return [len(nums), max(nums)]

