def shake_tree(tree):
    nuts, tree = [0 for _ in tree[0]], [a . replace('\\/', '__') for a in tree]

    for r, c in [(r, c) for r, row in enumerate(tree) for c, v in enumerate(row) if v == 'o']:
    for k in range(r, len(tree)):
    while tree[k][c] == '\\':
        c += 1
    while tree[k][c] == '/':
        c -= 1
    if tree[k][c] == '_':
        break
    else:
    nuts[c] += 1
    return nuts

