def calc_rot_time(box):
    def neighbours(z): return {z + 1j * * d for d in range(4)}
    time, fresh, rotten = 0, set(), set()
    for x, row in enumerate(box):
    for y, orange in enumerate(row):
    if orange == 1:
        fresh . add(x + 1j * y)
    if orange == 2:
        rotten . add(x + 1j * y)
    while fresh and rotten:
    time += 1
    rotten . update(* map(neighbours, rotten))
    rotten &= fresh
    fresh -= rotten
    return - 1 if fresh else time

