    def __init__(self, seq):
    self . seq = list(seq)
    for i in reversed(range(len(self . seq))):
    if not isinstance(self . seq[i], (int, float, complex)) or isinstance(self . seq[i], bool):
    self . seq . pop(i)  # Discard every value that is not a number
    self . seq . sort()  # Sort by value
    def __len__(self):  # Follow dunder standard
    return len(self . seq)

    def median(self):
    if len(self . seq) % 2 == 0:
    return (self . seq[int(len(self . seq) / 2)] + self . seq[int(len(self . seq) / 2 - 1)]) / 2
    else:
    return self . seq[len(self . seq) / / 2]

    def lower_quartile(self):
        # -1 to adjust for lists staring with index 0
    low = self . seq[(len(self) + 3) / / 4 - 1]
    high = self . seq[(len(self) + 3) / / 4]
    rest_fraction = (len(self) + 3) % 4 / 4
    return (1 - rest_fraction) * low + rest_fraction * high

    def upper_quartile(self):
        # -1 to adjust for lists staring with index 0
    low = self . seq[(len(self) * 3 + 1) / / 4 - 1]
    high = self . seq[(len(self) * 3 + 1) / / 4]
    rest_fraction = (len(self) * 3 + 1) % 4 / 4
    return (1 - rest_fraction) * low + rest_fraction * high
