def split_workload(workload):
    if not workload:
        return None, None
    diff = sum(workload)
    best_i, best_diff = None, float('inf')

    for i, work in enumerate(workload):
    if abs(diff) < best_diff:
    best_i, best_diff = i, abs(diff)

