import math


def factor_digit(n):
    if n < 0:
    return 0
    if n <= 1:
    return 1
    # Kamenetsky formula
    x = ((n * math . log10(n / math . e) + math . log10(2 * math . pi * n) / 2.0))
    return math . floor(x) + 1

