class Arith (object):
    # Constant names and associated ranges for natural numbers
    zero_nine = ("zero,one,two,three,four,five,six,seven,eight,nine", 0, 10, 1)
    ten_nineteen = (
        "ten,eleven,twelve,thirteen,fourteen,fifteen,sixteen,seventeen,eighteen,nineteen", 10, 20, 1)
    tens = ("twenty,thirty,forty,fifty,sixty,seventy,eighty,ninety", 20, 91, 10)
    hundreds = ("one hundred,two hundred,three hundred,four hundred,five hundred,six hundred,seven hundred,eight hundred,nine hundred,one thousand", 100, 1001, 100)

    @ classmethod
    def gen_vals(cls):
    """Generates a tuple of name and value for each value from largest to smallest"""
    for target in [cls . hundreds, cls . tens, cls . ten_nineteen, cls . zero_nine]:
    for name, value in zip(reversed(target[0]. split(",")), reversed(range(* target[1:]))):
    yield name, value
    @ classmethod
    def extract(cls, s):
    """Extracts the numerical value of s"""
    total = 0
    for name, value in cls . gen_vals():
    if name in s:
    total += value
    s = s . replace(name, "")
    return total
    @ classmethod
    def encode(cls, n):
    """Encodes the string value of n"""
    s = []
    for name, value in cls . gen_vals():
    if n >= value:
    s . append(name)
    n -= value
    if len(s) > 0 and s[- 1] == "zero":
        # Remove trailing zeros
    s = s[: - 1]

    if len(s) > 1:
    if " " in s[0]:
        # Found a hundred or thousand marker
    s = [s[0]] + ["and"] + s[1:]
    return " " . join(s)

    def __init__(self, s):
    self . value = self . extract(s)

    def add(self, s):
    return self . encode(self . value + self . extract(s))

