def super_street_fighter_selection(fighters, initial_position, moves):
    y, x = initial_position
    hovered_fighters = []
    for move in moves:
    dy, dx = MOVES[move]
    y += dy
    if not 0 <= y < len(fighters) or not fighters[y][x]:
    y -= dy
    x = (x + dx) % len(fighters[y])
    while not fighters[y][x]:
