def rot_pred(arr):
    pivot = len(arr) / / 2
    if not len(arr) % 2 or arr[pivot] != 'S':
        return 'Not a Valid Entry'
    moment = sum(i * x for i, x in enumerate(arr, - pivot) if i)
    return 'steady' if not moment else 'anti ' * (moment < 0) + 'clockwise'

