KNOWN_WORD = 'I already know the word %s'
NEW_WORD = 'Thank you for teaching me %s'


class Robot (object):

    def __init__(self):
    self . vocabulary = set(
        word . lower()
        for message in (BAD_INPUT, KNOWN_WORD, NEW_WORD)
        for word in message . split()
        if word != '%s')

    def learn_word(self, word):
    if not word . isalpha():
    return BAD_INPUT
    lc_word = word . lower()
    if lc_word in self . vocabulary:
    return KNOWN_WORD % word
    self . vocabulary . add(lc_word)
    return NEW_WORD % word

