def processes(start, end, processes):
    '''Dijkstra's shortest path algorithm'''
    q = [(start, [])]
    visited = set()

    while q:
    s, path = q . pop(0)
    if s == end:
        return path
    visited . add(s)
    for p in filter(lambda x: x[1] == s, processes):
    if not p[2] in visited:
    q . append((p[2], path + [p[0]]))
    return []

