    elif seconds < 3600 and seconds > 60:  # mini
    x = seconds / 60
    if int(x) == 1:
        return f"a minute ago"
    return f" { int ( x )} minutes ago"
    elif seconds > 3600 and seconds < 86400:  # hours
    x = seconds / 3600
    if int(x) == 1:
        return f"an hour ago"
    return f" { int ( x )} hours ago"
    elif seconds > 86400 and seconds < 604800:  # days
