    while p1 * * k1 * p2 * * k2 <= n:
    while p1 * * k1 * p2 * * (k2 + 1) <= n:
    k2 += 1
    factors[p1 * * k1 * p2 * * k2] = (k1, k2)
    k1, k2 = k1 + 1, 1
    m = max(factors)
    return [m, factors[m][0], factors[m][1]]

