end


recipe = [
  Instruction.new(5,"Sodium Chloride","Graduated Cylinder"),
  Instruction.new(250,"Hydrochloric Acid","Boiling Flask"),
  Instruction.new(100,"Water","Erlenmeyer Flask", "Do NOT mess this step up, Jesse!")
]

helpJesse(recipe);
