import math


def geometric_meanII(arr):
    gm = 0
    c = 0
    f = 0
    l = len(arr)
    for a in arr:
    if type(a) == int and a >= 0:
        gm += math . log(a)
        c += 1
    else:
        f += 1
    if l <= 10:
    if c < l - 1:
        return 0
    else:
    if f * 100 / l > 10:
        return 0
    return math . exp(gm / c)

