def shorten_number(suffixes, base):
    def filter(num_string):
    try:
    num = int(num_string)
    except:
    return str(num_string)
    suf_index = 0
    while num > base and suf_index < len(suffixes) - 1:
    num = num / / base
    suf_index += 1
    return str(num) + suffixes[suf_index]
    return filter

