def binary_simulation(s, q):
    out, n, s = [], int(s, 2), len(s)
    for cmd, * i in q:
    if cmd == 'I':
    a, b = i
    n ^= (1 << b - a + 1) - 1 << s - b
    else:
    out . append(str(int(0 < 1 << s - i[0] & n)))
    return out

from heapq import *


def shortest_path(topology, start, end):
    q, ans = [(0, 1, 1, start)], []
    while q[0][- 1][- 1] != end:
    time, _, _, path = heappop(q)
    for nextPt, dt in topology[path[- 1]]. items():
    heappush(q, (time + dt, len(path) + 1, nextPt != end, path + nextPt))

    minTime = q[0][0]
    while q[0][0] == minTime and q[0][- 1][- 1] == end:
    ans . append(heappop(q))
    ans = [list(path) for _, _, _, path in ans]

    return ans

from math import sqrt, ceil
REST_HEIGHT = 50
MIN_HEIGHT = 20


def optimal_one_building(pos, building, building_start):
    h, w = building
    theoretical = int(pos + sqrt(MIN_HEIGHT * * 2 - REST_HEIGHT * * 2 + 2 * h * (REST_HEIGHT - MIN_HEIGHT)))
    if max(pos, building_start) <= theoretical <= building_start + w:
    return theoretical, sqrt((theoretical - pos) * * 2 + (h - REST_HEIGHT) * * 2)
    rope_length = sqrt((building_start + w - pos) * * 2 + (h - REST_HEIGHT) * * 2)
    if rope_length <= h - MIN_HEIGHT:
    return building_start + w, rope_length
    def final_latch(pos, buildings, w_start, w_end):
    options = {}
    for h, w in buildings:
    mid = ceil(pos + (w_end - pos) / 2)
    if mid > w_start + w:
    w_start += w
    continue
    if mid >= w_start:
    rope = sqrt((mid - pos) * * 2 + (h - REST_HEIGHT) * * 2)
    if rope > h - MIN_HEIGHT:
    w_start += w
    continue
    options[mid] = (w_end - pos) / rope
    else:
    rope = sqrt((w_start - pos) * * 2 + (h - REST_HEIGHT) * * 2)
    if rope > h - MIN_HEIGHT:
    w_start += w
    continue
    options[w_start] = (w_end - pos) / rope
    w_start += w
    if options:
    return max(options, key=options . get)

    def spidey_swings(buildings):
    print(buildings)
    w_total = sum(w for h, w in buildings)

    latchpoints = []
    pos = 0
    i_building = l_building = 0
    while True:
    final = final_latch(pos, buildings[i_building:], l_building, w_total)
    if final is not None:
        return [int(l) for l in latchpoints + [final]]

    candidates = {}
    building_start = l_building
    for h, w in buildings[i_building:]:
    if (latchrope := optimal_one_building(pos, (h, w), building_start)) is not None:
    latch, rope = latchrope
    candidates[latch] = (latch - pos) / rope
    building_start += w
    latchpoints . append(max(candidates, key=candidates . get))

    pos = 2 * latchpoints[- 1] - pos
    for h, w in buildings[i_building:]:
    if pos < l_building + w:
        break
    i_building += 1
    l_building += w

from math import dist
from typing import Dict, List, Tuple
DIRECTIONS = (0, 1, - 1)


def tower_defense(
    grid: List[str], turrets: Dict[str, List[int]], aliens: List[int]
) - > int:

    def find_start_point() - > Tuple[int, int]:
    for index_row, row in enumerate(grid):
    if '0' in row:
    return index_row, row . find('0')

    def find_next_point() - > Tuple[int, int]:
    for i in range(3):
    for direction in DIRECTIONS:
    if (path := roadmap . get(start + direction)) and DIRECTIONS[i] + finish in path:
    return start + direction, DIRECTIONS[i] + finish
    return 0, 0
    def find_targets_turrets() - > Dict[Tuple[Tuple[int, int], ...], int]:
    turret_positions = {item: (row, col) for row in range(len(grid))
                        for col, item in enumerate(grid[row]) if item . isalpha()}

    return {tuple(point for point in alien_path
                  if dist(pos, point) <= turrets[turret][0]): turrets[turret][1]
            for turret, pos in turret_positions . items()}

    roadmap = {row: [col for col, item in enumerate(grid[row]) if item . isdigit()]
               for row in range(len(grid))}

    start, finish = find_start_point()
    alien_path = []
    while any(roadmap[row] for row in roadmap . keys()):
    point_index = roadmap[start]. index(finish)
    alien_path . append((start, roadmap[start]. pop(point_index)))
    start, finish = find_next_point()

    alien_killer = AlienKiller(alien_path, find_targets_turrets(), aliens)
    alien_survivors_hp = sum(
        alien_killer . get_aliens_survivor_health_points())

    return alien_survivors_hp
    class AlienKiller:

    def __init__(
        self,
        path: List[Tuple[int, int]],
        turrets: Dict[Tuple[Tuple[int, int], ...], int],
        aliens: List[int]
    ) - > None:
    self . turrets = turrets
    self . total_turrets_shots = [shot for shot in turrets . values()]
    self . alien_path = path
    self . number_movements = len(aliens) + len(path)
    self . aliens = [0] * len(path) + aliens[:: - 1]
    self . target_list: List[Tuple[int, List[int]], ...] = []
    self . alien_survivors: List[int] = []

    def get_aliens_survivor_health_points(self) - > List[int]:
    for num in range(1, self . number_movements):
    target_list: Dict[int, List[int]] = {}
    self . alien_survivors . append(self . aliens[- num])
    for position, alien in enumerate(self . aliens[- num:][: len(self . alien_path)], 1):
    for turret_number, targets in enumerate(self . turrets):
    if alien and self . alien_path[position - 1] in targets:
    target_list[turret_number] = target_list . get(
        turret_number, []) + [- position]
    self . target_list = sorted(target_list . items(), key=lambda x: x[0])
    self . _open_fire_from_turrets()
    return self . alien_survivors
    def _open_fire_from_turrets(self) - > None:
    alien_positions = [pos for _, pos in self . target_list]
    shots = [self . total_turrets_shots[turret_queue]
             for turret_queue, _ in self . target_list]

    for _ in range(max(shots) if shots else 0):
    for i, shot in enumerate(shots):
    if shot and (targets := [pos for pos in alien_positions[i]
                             if self . alien_survivors[pos]]):
    self . alien_survivors[min(targets)] -= 1
    shots[i] -= 1

def change_detection(cls):
    class attr_cls ():
    def __init__(self, value, get_change='INIT'):
    self . value = value
    self . get_change = get_change
    def __getattr__(self, name):
    return getattr(self . value, name)

    def __repr__(self):
    return str(self . value)

    def __bool__(self):
    return bool(self . value)

    def __call__(self):
    return self . value()

    def __eq__(self, other):
    return self . value == other
    def __add__(self, other):
    return self . value + other
    def __sub__(self, other):
    return self . value - other
    def __mul__(self, other):
    return self . value * other
    def __truediv__(self, other):
    return self . value / other
    def __radd__(self, other):
    return other + self . value
    def __rsub__(self, other):
    return other - self . value
    def __rmul__(self, other):
    return other * self . value
    def __rtruediv__(self, other):
    return other / self . value
    def __getattribute__(self, name):
    try:
    attr = super(cls, self). __getattribute__(name)
    if type(attr) != attr_cls:
    new_attr = attr_cls(attr)
    super(cls, self). __setattr__(name, new_attr)
    return new_attr
    return attr
    except:
    return attr_cls(None, '')

    def __setattr__(self, name, value):
    target = getattr(self, name, None)
    if type(target) != attr_cls or not target . get_change:
    super(cls, self). __setattr__(name, attr_cls(value))
    elif target . value != value or type(target . value) != type(value):
    target . value = value
    target . get_change = 'MOD'
    def __delattr__(self, name):
    target = getattr(self, name)
    target . value = None
    target . get_change = 'DEL'
    setattr(cls, '__setattr__', __setattr__)
    setattr(cls, '__getattribute__', __getattribute__)
    setattr(cls, '__delattr__', __delattr__)

    return cls

from itertools import repeat, groupby, count, chain
import random


def solve(* args):
    return tuple(map(tuple, Nonogram(* args). solve()))

    class Memo:
    def __init__(self, func):
    self . func = func
    self . cache = {}

    def __call__(self, * args):
    if args in self . cache:
    return self . cache[args]
    else:
    ans = self . func(* args)
    self . cache[args] = ans
    return ans
    class Nonogram:

    __slots__ = ['W', 'H', 'no_of_lines', 'col_clues', 'row_clues',
                 'grid', 'to_linesolve', 'grid_changed', 'solved_lines',
                 'prev_states']

    def __init__(self, clues, width, height):
    self . W, self . H = width, height
    self . no_of_lines = width + height
    self . col_clues, self . row_clues = clues
    self . grid = [[- 1 for _ in range(width)] for _ in range(height)]

    self . to_linesolve = sorted(list(zip(repeat('C'), count(), self . col_clues))
                                 + list(zip(repeat('R'), count(),
                                        self . row_clues)),
                                 key=lambda x: sum(x[2]), reverse=True)

    self . solved_lines = set()  # set of all the solved lines for lookup
    self . prev_states = []  # list of states in case it needs to guess and backtrack
    def solve(self):
    """Generates the furthest left, and furthest right possible permutation of a row 
 and takes the intersection of the points that are the same (line-solving). 
 If no more points can be deduced, then it takes a random guess and repeats. 
 If the grid becomes invalid, it just backtracks to the last guess."""
    line_solve = self . line_solve
    while len(self . solved_lines) < self . no_of_lines:
    self . grid_changed = False
    try:
    line_solve()
    except InvalidGridError:
        # Resets the grid back to the old state.
    old_grid, old_guess, guess_pos, old_solved_lines = self . prev_states . pop()
    self . grid = [l[:] for l in old_grid]
    self . grid[guess_pos[0]][guess_pos[1]] = old_guess ^ 1  # Swaps the guess
    self . solved_lines = old_solved_lines . copy()
    continue
    if not self . grid_changed and len(self . solved_lines) < self . no_of_lines:
        # Guesses if no extra blocks/gaps have been deduced
    self . guess()
    return self . grid
    def line_solve(self):
    """This method should line solve all the clues in self.line_solve 
 using the furthest left, and furthest right to compare which blocks are valid/invalid. 
 It may miss a small amount though (limitations of alg), but 'should' be fast(ish)"""
    solved_lines = self . solved_lines
    get_line = self . get_line
    linesolve_helper = self . linesolve_helper
    change_grid = self . change_grid
    for vert, pos, clue in self . to_linesolve:

    if (vert, pos, clue) in solved_lines:
        # If the line is already solved
    continue
    line = get_line(vert, pos)  # The current line so far
    solved = linesolve_helper(line, clue)

    if solved is True:
        # The line must be solved
    solved_lines . add((vert, pos, clue))
    elif solved:
        # Changes the grid if the line changed
    change_grid(solved, vert, pos)
    self . grid_changed = True
    def guess(self):
    """Guesses a random choice if nothing can be deduced from linesolving"""
    guess = random . choice((0, 1))

    target = self . find_guess_target()

    # Incase the guess is wrong and needs to backtrack
    self . prev_states . append(([l[:] for l in self . grid],
                                 guess, target,
                                 self . solved_lines . copy()))
    self . grid[target[0]][target[1]] = guess
    def find_guess_target(self):
    """Finds the first unkown square sorted by the length of the sum of the clue, 
 and therefore should be more likely to lead to a guess with more impact"""
    for vert, pos, clue in self . to_linesolve:
    if (vert, pos, clue) not in self . solved_lines:
    if vert == 'R':
    for i, b in enumerate(self . grid[pos]):
    if b == - 1:
    return (pos, i)
    elif vert == 'C':
    for i, r in enumerate(self . grid):
    if r[pos] == - 1:
    return i, pos
    def get_line(self, vert, pos):
    """Gets the specified line"""
    if vert == 'R':
    return tuple(self . grid[pos])
    elif vert == 'C':
    return tuple(row[pos] for row in self . grid)

    def change_grid(self, line, vert, pos):
    """Changes the line in the grid"""
    if vert == 'R':
    self . grid[pos] = list(line)
    elif vert == 'C':
    for i, val in enumerate(line):
    self . grid[i][pos] = val
    @ staticmethod
    @ Memo
    def linesolve_helper(line, clue):
    """This method first calculates the leftmost and 
 rightmost possible permutations of the line. 
 Then it find the intersection where there is a overlap of the same colour."""
    length = len(line)

    leftmost = Nonogram . get_leftmost(clue, length, line)
    rightmost = Nonogram . get_leftmost(
        clue[:: - 1], length, line[:: - 1])[:: - 1]

    solved = Nonogram . find_intersection(leftmost, rightmost, line, length)

    return solved if solved != line else not - 1 in line
    @ staticmethod
    @ Memo
    def get_leftmost(clue, length, filled_line):
    """This method should get the leftmost valid arrangement of all the clues."""
    # List of all blocks in order of clues given.
    # block is [start_pos, end_pos, length]
    blocks = tuple([0, c, c] for c in clue)

    for i, block in enumerate(blocks):
        # Moves the blocks up until they are all in valid positions,
        # but not necessarily covering all the blocked spots.
    if i != 0:
        # Teleports the block to the end of the previous block
    diff = blocks[i - 1][1] - block[0] + 1
    block[0] += diff
    block[1] += diff
    while 0 in filled_line[block[0]: block[1]]:
        # If the block is in an invalid position, then it moves it along 1 square
    block[0] += 1
    block[1] += 1
    while True:
        # Moves the blocks until all the blocked spots are covered.
    line = [0] * length
    # Fills in the line if a block is there.
    for block in blocks:
    line[block[0]: block[1]] = [1] * block[2]

    changed = False
    for i, c in enumerate(filled_line):
        # If a block should be covering a filled square but isn't
    if c == 1 and line[i] == 0:
    changed = True
    for block in reversed(blocks):
        # Finds the first block to the left of the square,
        # and teleports the right end of the block to the square
    if block[1] <= i:
    diff = i - block[1] + 1
    block[0] += diff
    block[1] += diff
    break
    else:
        # If no block was found, then the grid must be invalid.
    raise InvalidGridError('Invalid grid')

    if not changed:
    break
    for i, block in enumerate(blocks):
        # Moves the blocks up until they are not covering any zeros,
        # but not necessarily covering all the blocked spots,
    while 0 in filled_line[block[0]: block[1]]:
        # If the block is in an invalid spot
    block[0] += 1
    block[1] += 1
    if i != 0:
        # If any block is in an invalid position compared to the previous block
    if block[0] <= blocks[i - 1][1]:
        # Teleports the block to 1 square past the end of the previous block
    diff = blocks[i - 1][1] - block[0] + 1
    block[0] += diff
    block[1] += diff
    return tuple(line)

    @ staticmethod
    def find_intersection(left, right, line, length):
    """Groups the same blocks together then takes the intersection."""
    leftmost = list(
        chain . from_iterable([i] * len(list(g[1]))
                              for i, g in enumerate(groupby((0,) + left))))[1:]
    rightmost = list(
        chain . from_iterable([i] * len(list(g[1]))
                              for i, g in enumerate(groupby((0,) + right))))[1:]

    solved = tuple(line[i] if line[i] != - 1 else - 1 if leftmost[i] != rightmost[i]
                   else leftmost[i] % 2 for i in range(length))

    return solved
    class InvalidGridError (Exception):
    """Custom Exception for an invalid grid."""

def dist_same_letter(st):
    dist_dict = {}
    for k, x in enumerate(st):
    dist_dict[x] = dist_dict . get(x, []) + [k]

    lt = max(dist_dict, key=lambda k: dist_dict[k][- 1] - dist_dict[k][0])
    return f' { lt }{ dist_dict [ lt ][ - 1 ] - dist_dict [ lt ][ 0 ] + 1 } '

def get(x): return x if callable(x) else lambda s, c: c(
    s, s[x] if isinstance(x, str) else x)


def start(x): return x({}, None)


def return_(s, c): return lambda x: get(x)(s, lambda _s, x: x)


def let(s, c): return lambda x: lambda y: get(y)(s, lambda s, y: lambda z: z({* * s, x: y}, None))


def add(s, c): return lambda x: get(x)(s, lambda s,
                                       x: lambda y: get(y)(s, lambda s, y: c(s, x + y)))


def sub(s, c): return lambda x: get(x)(s, lambda s,
                                       x: lambda y: get(y)(s, lambda s, y: c(s, x - y)))


def mul(s, c): return lambda x: get(x)(s, lambda s,
                                       x: lambda y: get(y)(s, lambda s, y: c(s, x * y)))


def div(s, c): return lambda x: get(x)(s, lambda s, x: lambda y: get(y)(s, lambda s, y: c(s, x / / y)))

import math


class Blobservation:

    def __init__(self, height, width=None):
    self . height = height
    self . width = width or height
    self . blobs = {}  # {(x, y): size}
    def populate(self, blobs):
    for blob in blobs:
    assert type(blob['x']) == type(blob['y']) == type(blob['size']) == int
    assert 0 <= blob['x'] <= self . height and 0 <= blob['y'] <= self . width and blob['size'] > 0
    for blob in blobs:
    pos, size = (blob['x'], blob['y']), blob['size']
    self . blobs[pos] = self . blobs . get(pos, 0) + size
    def move(self, generations=1):
    assert generations >= 1 and type(generations) == int
    _total_size = sum(self . blobs . values())
    for _ in range(generations):
    if len(self . blobs) == 1:
    break
    new_blobs = {}
    for pos, size in self . blobs . items():
    target = min((p for p, s in self . blobs . items() if s < size),
                 key=lambda p: (self . _calc_dist(pos, p),
                                - self . blobs[p],
                                self . _calc_angle(pos, p)),
                 default=pos)
    dx, dy = target[0] - pos[0], target[1] - pos[1]
    new_pos = pos[0] + (dx and dx / / abs(dx)), pos[1] + (dy and dy / / abs(dy))
    new_blobs[new_pos] = new_blobs . get(new_pos, 0) + size
    self . blobs = new_blobs
    def print_state(self):
    return sorted([* p, s] for p, s in self . blobs . items())

    @ staticmethod
    def _calc_dist(p1, p2):
    return max(abs(p2[0] - p1[0]), abs(p2[1] - p1[1]))

    @ staticmethod
    def _calc_angle(p1, p2):
    dx, dy = p2[0] - p1[0], p2[1] - p1[1]
    raw_angle = math . atan(- dy / dx) if dx != 0 else math . pi / \
        2 if dy > 0 else - math . pi / 2
    angle = raw_angle + (0 if dy >= 0 and dx <=
                         0 else math . pi if dy >= 0 or dx > 0 else 2 * math . pi)
    return angle

from itertools import chain


def plants_and_zombies(lawn, zProvider):

    DEBUG = False
    X, Y = len(lawn), len(lawn[0])

    class Stuff (object):  # Shooters and Zombies instances
    def __init__(self, x, y, typ, h=0):
    self . x, self . y = x, y
    self . isS = typ == 'S'
    self . fire = int(typ) if typ not in 'SZ' else 1
    self . h = h
    def __str__(self): return 'S' if self . isS else str(
        self . h) if self . h else chr(self . fire + 64)

    def __repr__(self): return "({},{})" . format(self . x, self . y)
    def __bool__(self): return bool(self . h)  # Behave as "isZomby()"
    def __eq__(
        self, other): return self . x == other . x and self . y == other . y
    # The hash method reflects only the position in the board, so that a zomby and a shooter at the same position will have the same hash value
    def __hash__(self): return self . x * X + self . y
    def move(self): self . y -= 1  # for zombies
    def damage(self, d): self . h -= d  # for zombies
    def display():
    if DEBUG:
    print('' . join("{: >2d}" . format(y)
          for y in range(Y)), "\n" + "-" * (2 * Y))
    board = [[' '] * Y for _ in range(X)]
    for s in chain(sS, sN, * zombiesRows):
    board[s . x][s . y] = "{: >2}" . format(str(s))
    print('\n' . join(map('' . join, board)), "\n" + "-" * (2 * Y) + "\n")

    def makeFire(s, dir=0):  # dir = -1: diag up / 0: straight / 1: diag down
      # Initiate a fake zombie at the shooter position (allow to continue the exploration of the current direction at the last found zombie)
    nFire, z = s . fire, s
    while nFire:
    if not dir:
        # Shoot straight = easy target
        z = zombiesRows[z . x] and zombiesRows[z . x][0] or None
    else:
    z, x, y = None, z . x, z . y
    # Shoot diag: seek a matching position in each row...
    while z is None and 0 <= x + dir < X and y + 1 < Y:
    x += dir
    y += 1
    if not zombiesRows[x]:
        continue
    z = next((z for z in zombiesRows[x] if z . x == x and z . y == y), None)

    if z is None:
        break  # Not any zomby ahead... So sad...
    d = min(nFire, z . h)
    nFire -= d  # Update the number of shots
    z . damage(d)  # Damage the current zomby...
    if not z . h:
        zombiesRows[z . x]. remove(z)  # ...and "kill" it if necessary
    pZ, round = 0, - 1  # Initiate the pointer to zProvider index and the round number
    sN, sS = set(), set()  # Sets of numbered and S shooters
    for x, line in enumerate(lawn):
    for y, c in enumerate(line):
    if c != ' ':
    (sS if c == 'S' else sN). add(Stuff(x, y, c))
    # List of all the S shooters, in required order
    sSlst = sorted(sS, key=lambda s: (- s . y, s . x))
    # List of rows of zomby objects (to identify easily thos at the front, facing the shooters)
    zombiesRows = [[] for _ in range(X)]
    # Continue while zombies have to enter the lawn or while some aren't destroyed yet
    while pZ < len(zProvider) or any(map(bool, zombiesRows)):
    round += 1
    # New zombies (outside of the map, will move into just after)
    while pZ < len(zProvider) and zProvider[pZ][0] == round:
    row, h = zProvider[pZ][1:]
    zombiesRows[row]. append(Stuff(row, Y, 'Z', h))
    pZ += 1
    for row in zombiesRows:
    for z in row:
    if not z . y:
        return round  # End of game: crushed defenses...
    else:  # ...or move forward and destroy shooters if needed
    z . move()
    if z in sS:
        sS . remove(z)
    if z in sN:
        sN . remove(z)

    for s in sN:
        makeFire(s)  # Numbered shooters firing first
    for s in sSlst:  # S shooters firing in order...
    if s in sS:  # ...only if the S shooter hasn't been destroyed yet...
    for d in [- 1, 0, 1]:
        makeFire(s, d)  # Shoot in the 3 directions
    if DEBUG:
    print(round, sum(map(len, zombiesRows)))
    display()

from itertools import count
from collections import deque, defaultdict


def converge(g, us):
    us = set(us)
    cnts = (defaultdict(int), defaultdict(int))
    floods = [[[u], ({u}, set())] for u in us]
    tic, N = 0, len(us)

    for u in us:
    cnts[tic][u] += 1
    if cnts[tic][u] == N:
        return 0
    for step in count(1):
    tic ^= 1
    for i, (bag, seens) in enumerate(floods):
    if not bag:
        return None
    tmp = []
    for node in bag:
    for neigh in g[node]:
    if neigh in seens[tic]:
        continue
    seens[tic]. add(neigh)
    cnts[tic][neigh] += 1
    if cnts[tic][neigh] == N:
        return step
    tmp . append(neigh)
    else:
    floods[i][0] = tmp

class Hand:
    ORDER = 'A23456789TJQK'
    PTS = {f: i for i, f in enumerate(ORDER, 1)}

    def __init__(self, hand):
    self . h = hand[:]
    self . score = float('inf')
    self . discard = None
    self . study()

    def get_hand(self): return self . h[:]
    def get_score(self): return self . score
    def add_card(self, c):
    if not self . score:
        return c
    self . h . append(c)
    self . discard = c
    self . study()
    return self . discard
    @ staticmethod
    def cardScore(c): return Hand . PTS[c[0]]

    @ staticmethod
    def buildMeldOf(lst):
    target = lst[- 1][0]
    meld = [c for c in lst if c[0] == target]
    if len(meld) >= 3:
        yield [c for c in lst if c[0] != target]
    if len(meld) == 4:
    for i in range(4):
        yield [c for c in lst if c[0] != target or c == meld[i]]

    @ staticmethod
    def buildRunOf(lst):
    (face, col), r = lst[- 1], [lst[- 1]]
    s = {c for c in lst if c[1] == col and face != c[0]}
    iFace = Hand . cardScore(lst[- 1]) - 1
    while iFace:
    iFace -= 1
    nc = Hand . ORDER[iFace] + col
    if nc not in s:
        break
    r . append(nc)
    s . discard(nc)

    tailAce = 'A' + col
    tailing = face == 'K' and tailAce in s
    sR = set(r)
    while len(r) + tailing > 2:
    if tailing and len(r) > 1:
        yield [c for c in lst if c not in sR and c != tailAce]
    if len(r) > 2:
        yield [c for c in lst if c not in sR]
    sR . discard(r . pop())

    def study(self):

    def dfs(lst):
    if len(lst) < 3:  # end of search...
    end = sorted(out + lst, key=Hand . cardScore)
    if isDiscard and not end:
        return
    rem = end . pop() if isDiscard else None
    score = sum(map(Hand . cardScore, end))
    if self . score > score:
    self . score, self . discard = score, rem
    else:
        # melds then runs, built on the current last card
    for genFunc in (self . buildMeldOf, self . buildRunOf):
    for others in genFunc(lst):
    dfs(others)

    out . append(lst[- 1])  # nothing doable with this card...
    dfs(lst[: - 1])
    out . pop()

    isDiscard, out = len(self . h) == 8, []
    dfs(sorted(self . h, key=Hand . cardScore))
    if isDiscard:
    self . h . remove(self . discard)

from collections import deque, defaultdict
from functools import cache


def parse(s):
    name, rest = s . split(":")
    lst = rest . split(" ")
    if lst[- 1] == "position.":
        return (name, int("" . join(c for c in lst[- 2] if c . isdigit())))
    elif lst[0] == "There":
    if lst[- 2] == "of":
        return (name, int(lst[2]) + 1)
    else:
        return (name, - int(lst[2]))
    elif lst[2] == "behind":
        return (name, lst[- 1][: - 1], 1)
    else:
        return (name, lst[- 1][: - 1], - 1)

    @ cache
    def validate(blanks, strands):
    if blanks == strands:
        return True
    if strands[- 1] > blanks[- 1]:
        return False
    next_blanks = []
    next_strands = []

    i, j = 0, 0
    while i < len(blanks) and j < len(strands):
    if blanks[i] == strands[j]:
    i += 1
    j += 1
    elif blanks[i] > strands[j]:
    next_strands . append(strands[j])
    j += 1
    else:
    next_blanks . append(blanks[i])
    i += 1
    if i < len(blanks):
        next_blanks += blanks[i:]
    if j < len(strands):
        next_strands += strands[j:]

    if not next_blanks:
        return True
    for x in set(next_blanks):
    if x < next_strands[- 1]:
        continue
    next_blanks . remove(x)
    next_blanks . append(x - next_strands[- 1])
    if validate(tuple(sorted(next_blanks)), tuple(next_strands[: - 1])):
        return True
    next_blanks . remove(x - next_strands[- 1])
    next_blanks . append(x)
    return False
    class FinalDict (dict):
    def __init__(self, n):
    self . arr = [""] * (n + 1)
    self . n = n
    super(). __init__()

    def __setitem__(self, key, value):
    if key in self and self[key] != value:
        raise ValueError(f" { key } { value } { self } ")
    if value <= 0 or value > self . n:
        raise ValueError(f" { key } { value } { self } ")
    if self . arr[value] == key:
        return
    if self . arr[value]:
        raise ValueError(f" { key } { value } { self } ")
    self . arr[value] = key
    super(). __setitem__(key, value)

    def find_out_mr_wrong(conversation):
    cond = [parse(s) for s in conversation]
    cond_by_name = defaultdict(list)
    for name, * rest in cond:
    cond_by_name[name]. append(rest)
    n = len(cond_by_name)  # number of people
    wrong = ""  # answer
    for target, target_cond_lst in cond_by_name . items():  # assume target is Mr.Wrong
    try:
    d = FinalDict(n)
    rem = deque()

    # fix position for I'm ~ position for true statement
    for name, cond_lst in cond_by_name . items():
    if name == target:
        continue
    for c in cond_lst:
    match c:
    case(index,): d[name] = index if index > 0 else n + index
    case(other, rel_pos):
    if name in d:
        d[other] = d[name] + rel_pos
    elif other in d:
        d[name] = d[other] - rel_pos
    else:
        rem . append((name, other, rel_pos))

    # fix position (with consideration of relative pos information) for true statement
    fix_d = None
    strands = []  # not-fixed chain of people
    while rem:
    next_rem = []
    for name, other, rel_pos in rem:
    if name in d:
        d[other] = d[name] + rel_pos
    elif other in d:
        d[name] = d[other] - rel_pos
    else:
        next_rem . append((name, other, rel_pos))

    if next_rem == rem:
    if fix_d is None:
        fix_d = d
    else:
        strands . append(d)
    d = FinalDict(2 * n)  # to check statement is consistent
    d[name] = n
    rem = next_rem
    if fix_d is not None:
        strands . append(d)
    else:
        fix_d = d
    strands_lst = []
    # chain of people including target. If target is fixed this value is not used
    target_strands = []
    target_is_fixed = target in fix_d
    for strand in strands:
    tmp = [x for x in strand . arr if x]
    if target in tmp:
        target_strands = tmp
    else:
        strands_lst . append(tmp)
    if (not target_is_fixed) and (not target_strands):
        target_strands = [target]  # target does not appear in true statement
    strands_len_lst = sorted(len(x) for x in strands_lst)

    possible_target_pos = []
    if target_is_fixed:
        possible_target_pos = [fix_d . arr . index(target)]
    else:
    l = len(target_strands)
    target_pos = target_strands . index(target)
    bef = 0
    # check whether target_strand be put. i id last element index of target strand
    for i in range(1, n + 1):
    if fix_d . arr[i]:
        bef = i
    elif i - bef >= l:
        possible_target_pos . append(i - l + (target_pos + 1))

    for i in possible_target_pos:  # when target is position i, check whetehr it is possible to meet the all statement
    if any(len(c) == 1 and i == c[0] + n * (c[0] <= 0) for c in target_cond_lst):
        continue  # check whether Mr.wrong statement for position is wrong
    # when we have freedom to left-hand side or right-side of target, try fixing left and right strand and check
    # when they are fixed, use string indicating the name of left(right)-hand side person of these name instead.
    left_possible_strands = []
    right_possible_strands = []
    if i > 1 and (not fix_d . arr[i - 1]) and (target_is_fixed or target_pos == 0):
    l = 1
    while i - l > 0 and not fix_d . arr[i - l]:
        l += 1
    for strand in strands_lst:
    if len(strand) < l:
        left_possible_strands . append(strand)
    else:
    left_possible_strands . append("" if i == 1 else (
        fix_d . arr[i - 1] or target_strands[target_pos - 1]))

    if i < n and (not fix_d . arr[i + 1]) and (target_is_fixed or target_pos == len(target_strands) - 1):
    l = 1
    while i + l <= n and not fix_d . arr[i + l]:
        l += 1
    for strand in strands_lst:
    if len(strand) < l:
        right_possible_strands . append(strand)
    else:
    right_possible_strands . append("" if i == n else (
        fix_d . arr[i + 1] or target_strands[target_pos + 1]))

    if not left_possible_strands or not right_possible_strands:
        continue
    blanks = []  # strands of the sizes of continuous not-fixed block
    l = 0
    for j in range(1, n + 1):
    if fix_d . arr[j]:
    if j - l > 1:
    blanks . append(j - l - 1)
    l = j
    if j == i:
    target_blank_index = len(blanks)
    if l != n:
        blanks . append(n - l)

    for l_strand in left_possible_strands:
    for r_strand in right_possible_strands:
    if l_strand and l_strand == r_strand:
        continue
    left = l_strand if isinstance(l_strand, str) else l_strand[- 1]
    right = r_strand if isinstance(r_strand, str) else r_strand[0]
    # check whether Mr.wrong statement for relative position is wrong
    if any(1 <= i + c[1] <= n and [left, right][(c[1] + 1) / / 2] == c[0] for c in target_cond_lst if len(c) == 2):
        continue
    temp = blanks[:]
    strands_len_temp = strands_len_lst[:]
    if target_is_fixed:
    if isinstance(l_strand, list):
    temp[target_blank_index - 1] -= len(l_strand)
    strands_len_temp . remove(len(l_strand))
    if isinstance(r_strand, list):
    temp[target_blank_index] -= len(r_strand)
    strands_len_temp . remove(len(r_strand))
    else:
    temp[target_blank_index] -= len(target_strands)
    if isinstance(l_strand, list):
    temp[target_blank_index] -= len(l_strand)
    strands_len_temp . remove(len(l_strand))
    if isinstance(r_strand, list):
    temp[target_blank_index] -= len(r_strand)
    strands_len_temp . remove(len(r_strand))

    temp = tuple(x for x in sorted(temp) if x)
    # check whether we can put remaining starnds to blanks (in any order)
    # this method can be cached
    if validate(temp, tuple(strands_len_temp)):
    if wrong:
        return
    else:
    wrong = target
    break
    else:
        continue
    break
    else:
        continue
    break
    except ValueError as e:
        # Exception from FinalDict
    continue
    return wrong or None

LIMIT = 10 * * 7 / / 2
minimal_prime_factors = list(range(LIMIT + 1))
minimal_prime_factors[4:: 2] = (LIMIT / / 2 - 1) * [2]
for i in range(3, int((LIMIT + 1) * * .5) + 1, 2):
    if minimal_prime_factors[i] == i:
    for j in range(i * i, LIMIT + 1, i):
    if minimal_prime_factors[j] == j:
    minimal_prime_factors[j] = i
    from bisect import bisect
    common_sequence = [0, 1, 2]
    computed_steps, reached_indexes, tails = [0], [2], [[]]

    def prime_ant(n):
    closest_smaller_step = bisect(computed_steps, n) - 1
    idx = reached_indexes[closest_smaller_step]
    seq = common_sequence[: idx + 1] + tails[closest_smaller_step]
    for step in range(computed_steps[closest_smaller_step], n):
    m = minimal_prime_factors[seq[idx]]
    if m == seq[idx]:
    idx += 1
    if idx == len(seq):
        seq . append(idx)
    else:
    seq[idx] / /= m
    idx -= 1
    seq[idx] += m
    if step >= computed_steps[- 1]:
    common_sequence[idx:] = seq[idx:]
    while idx <= reached_indexes[- 1]:
    computed_steps . pop()
    reached_indexes . pop()
    tails . pop()
    computed_steps . append(step + 1)
    reached_indexes . append(idx)
    tails . append(common_sequence[idx + 1:])
    return seq[2: idx + 1]

from string import digits as d, ascii_uppercase as u, ascii_lowercase as l


def next_num(b, n, s=d + u + l):
    digits = {d: i for i, d in enumerate(s[: b])}
    nxt, n = False, [s[0]] + list(n)
    inc, ptr, x = False, 1, 0
    while 0 <= ptr < len(n):
    p = ptr + (ptr == 0 or n[0] > s[0])
    inc |= ptr == len(n) - 1 and nxt == False
    d = (x * b % p + digits[n[ptr]] + inc + p - 1) / / p * p - x * b % p
    if d >= b:
    inc, ptr, x = True, ptr - 1, x / / b
    continue
    if d > digits[n[ptr]]:
    nxt, n[ptr:] = True, [s[d]] + [s[0]] * (len(n) - ptr - 1)
    inc, ptr, x = False, ptr + 1, x * b + d
    if ptr >= 0:
    return '' . join(n). lstrip(s[0])

def calc(gamemap):
    nr, nc = len(gamemap), len(gamemap[0])
    def _i(ra, rb):
    return ra * nr + rb
    vs, ws = [0] * nr * * 2, [0] * nr * * 2
    for s in range(nr + nc - 1):
    for ra in range(max(0, s - nc + 1), min(s + 1, nr)):
    for rb in range(ra, min(s + 1, nr)):
    ws[_i(ra, rb)] = (
        gamemap[ra][s - ra] +
        (gamemap[rb][s - rb] if ra != rb else 0) +
        max(vs[_i(ra - da, rb - db)]
            for da in (0, 1) if da <= ra
            for db in (0, 1) if db <= rb))
    vs, ws = ws, vs
    return vs[- 1]

def maximum_clique(adjacency):
    """Maximum clique algorithm by Carraghan and Pardalos"""
    if not adjacency:
        return set()

    graph = {}
    for a, row in enumerate(adjacency):
    for b, connected in enumerate(row):
    if connected:
    graph . setdefault(a, set()). add(b)
    if not graph:
        return {0}

    def clique_search(subset, clique):
    nonlocal max_clique
    if not subset:
    max_clique = max((max_clique, clique), key=len)
    return
    while subset:
    if len(subset) + len(clique) <= len(max_clique):
    return
    x = subset . pop()
    clique_search(subset & graph[x], clique | {x})

    max_clique = set()
    clique_search(set(graph), set())
    return max_clique

from heapq import heapify, heappop, heappush


def volume(heightmap):
    N, M = len(heightmap), len(heightmap[0])

    if N < 3 or M < 3:
    return 0
    heap, seen = [], [[0] * M for _ in range(N)]
    for x in range(N):
    for y in range(M):
    if not x * y or x + 1 == N or y + 1 == M:
    heap . append((heightmap[x][y], x, y))
    seen[x][y] = 1
    heapify(heap)

    water, level = 0, - float('inf')
    while heap:
    height, x, y = heappop(heap)
    level = max(level, height)
    for i, j in (x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1):
    if N > i >= 0 <= j < M and not seen[i][j]:
    heappush(heap, (heightmap[i][j], i, j))
    water += max(0, level - heightmap[i][j])
    seen[i][j] = 1
    return water

from math import factorial
dyck = [factorial(2 * i) / / (factorial(i) * factorial(i + 1)) for i in range(201)]


def dyck_triangle(n):
    arr = [[0 for j in range(2 * n + 1)] for i in range(n + 1)]
    for i in range(n + 1):
    arr[i][2 * n - i] = 1
    for i in range(n + 1):
    arr[0][2 * (n - i)] = dyck[i]
    for k in range(1, n):
    for i in range(1, n - k + 1):
    arr[i][2 * (n - k) - i] = arr[i + 1][2 * (n - k) - i + 1] + \
        arr[i - 1][2 * (n - k) - i + 1]
    return arr
    def balanced_parens(m, n):
    if n < 0 or n > dyck[m] - 1:
    return None
    arr = dyck_triangle(m)
    x, y = 0, 0
    if n == 0:
        return "(" * m + ")" * m
    st = ""
    while n > 0:
    while arr[x + 1][y + 1] > n:
    x, y = x + 1, y + 1
    st += "("
    n -= arr[x + 1][y + 1]
    x, y = x - 1, y + 1
    st += ")"
    if n == 0:
    st += "(" * (m - (x + y) / / 2)
    st += ")" * (m - (y - x) / / 2)
    return st

def knapsack(items, w_limit):
    dpt = {0: [[0, [[]]] for _ in range(w_limit + 1)]}
    for i in range(len(items)):
    dpt[i + 1] = []
    for j in range(w_limit + 1):
    if items[i][0] > j or dpt[i][j - items[i][0]][0] + items[i][1] < dpt[i][j][0]:
    dpt[i + 1]. append(dpt[i][j])
    elif dpt[i][j - items[i][0]][0] + items[i][1] == dpt[i][j][0]:
    dpt[i + 1]. append([dpt[i][j][0], dpt[i][j][1] + [x + [items[i][1]]
                       for x in dpt[i][j - items[i][0]][1]]])
    else:
    dpt[i + 1]. append([dpt[i][j - items[i][0]][0] + items[i][1],
                       [x + [items[i][1]] for x in dpt[i][j - items[i][0]][1]]])

    return [dpt[len(items)][- 1][0], sorted(map(list, {tuple(sorted(x)) for x in dpt[len(items)][- 1][1]}))]

from heapq import *
import re
MOVES = ((0, 1), (0, - 1), (1, 0), (- 1, 0))
BACK = {dxy: c for dxy, c in zip(MOVES, '→←↓↑')}


def three_dots(game_map):

    class Dot:
    __slots__ = 'rgy h dist' . split()

    def __init__(self, dct, chars='rgy', d=None):
    self . rgy = r, g, y = tuple(map(dct . __getitem__, chars))
    self . h = r + tuple(v for x, y in (g, y) for v in (x - r[0], y - r[1]))
    self . dist = sum((a - b) * * 2 for a, b in zip(self . h, TARGET . h)) if d is None else d
    def __repr__(self): return f'Dot(* { self . rgy } )'
    def __hash__(self): return hash(self . h)
    def __eq__(self, o): return self . h == o . h
    def __lt__(self, o): return self . dist < o . dist
    def move(self, dx, dy):
    def closest_to_obstacle_ahead(t): return - (t[0] * dx + t[1] * dy)
    closest = sorted(((x, y, c) for (x, y), c in zip(
        self . rgy, 'rgy')), key=closest_to_obstacle_ahead)
    used, d = [], {}
    for x, y, c in closest:
    pos = a, b = x + dx, y + dy
    if not board[a][b]. isspace() or pos in used:
        pos = x, y
    used . append(pos)
    d[c] = pos
    return Dot(d)

    bd = game_map . splitlines()
    chars = {c: (i, j) for i, r in enumerate(bd)
             for j, c in enumerate(r) if c . isalpha()}
    TARGET = Dot(chars, d=0)
    start = Dot(chars, 'RGY')
    board = [re . sub(r'\w', ' ', r) for r in bd]
    seen = {start}
    prev = {start: (None, None)}
    h = [start]
    path = []

    while h:
    node = heappop(h)
    if node == TARGET:
        break
    for dxy in MOVES:
    new = node . move(* dxy)
    if new not in seen:
    prev[new] = (node, dxy)
    seen . add(new)
    heappush(h, new)
    while 1:
    node, dxy = prev[node]
    if node is None:
        break
    path . append(BACK[dxy])

    return '' . join(reversed(path))

def get_right_truncatable_primes(base):
    primes, bag = [], list(filter(fast_is_prime, range(2, base)))
    while bag:
    leaf, n = True, bag . pop(0)
    for x in range(base * n, base * (n + 1)):
    if fast_is_prime(x):
    leaf = False
    bag . append(x)
    if leaf:
    primes . append(n)
    return primes

from math import factorial, comb, gcd
from collections import Counter
from functools import reduce


def partition(n, xs):
    if not xs:
    return 0 if n else 1
    h, * t = xs
    return sum(comb(h, k) * partition(n - k, t) for k in range(min(h, n + 1)))

    def count(x, xs):
    n = x + sum(xs)
    return x * sum(factorial(i - 1) * factorial(n - i) * partition(i - x, xs) for i in range(x, n - len(xs) + 1))

    def pick_until_match(meters, points):
    c = Counter()
    for m in meters:
    c[points[m]] += count(meters[m],
                          [x for k, x in meters . items() if k != m])
    d = reduce(gcd, c . values())
    return {k: v / / d for k, v in c . items()}

def find_vertices(adj):
    opt, todo = set(), {* range(len(adj))}
    while todo:
    new = {x for x in todo if not any(adj[y][x] for y in todo)}
    todo -= new
    todo -= {x for y in new for x in todo if adj[y][x]}
    opt |= new
    return sorted(opt)

def parse_term(s, start=0):
    terms = []

    i = start
    while i < len(s):
    c = s[i]
    i += 1
    if c == '(':
    term, end = parse_term(s, i)
    terms . append(term)
    i = end
    elif c == 'λ':
    fn, end = parse_fn(s, i)
    terms . append(fn)
    i = end
    elif c == ')':
    break
    else:
    terms . append(c)

    t = terms[0]
    for term in terms[1:]:
    t = [t, term]

    return t, i
    def parse_fn(s, start=0):
    i = start
    args = []

    while s[i] != '.':
    args . append(s[i])
    i += 1
    i += 1
    term, end = parse_term(s, i)
    for arg in args[:: - 1]:
    term = (arg, term)
    return term, end
    def free(term, var):
    match term:
    case str(x):
    return x == var
    case tuple((_, e)):
    return free(e, var)
    case list([e1, e2]):
    return free(e1, var) or free(e2, var)

    def translate(term):
    match term:
    case str(x):
    return x
    case list([a, b]):
    return [translate(a), translate(b)]
    case tuple((str(x), e)) if not free(e, x):
    return ['K', translate(e)]
    case tuple((str(x), str(y))) if x == y:
    return 'I'
    case tuple((str(x), tuple((str(y), e)))) if free(e, x):
    return translate((x, translate((y, e))))
    case tuple((str(x), list([e1, e2]))):
    return ([['S', translate((x, e1))], translate((x, e2))])

    def repr(tree):
    if isinstance(tree, list):
    return f"( { repr ( tree [ 0 ])} )( { repr ( tree [ 1 ])} )"
    return tree
    def eliminate(s):
    fn, _ = parse_fn(s[1:])
    print(fn)
    trans = translate(fn)
    print(trans)
    return repr(trans)

def count_diamonds(a, q):
    n = len(a)
    m = len(a[0])
    if q == 0:
        return [[[i, j], [i, j]] for i in range(n) for j in range(m) if a[i][j] == 0]
    ans = []
    size = n * m
    for u in range(n):
    s = [0] * (m)
    for d in range(u, n):
    l = 0
    cur = 0
    for r in range(m):
    s[r] += a[d][r]
    cur += s[r]
    while cur - s[l] >= q:
    cur -= s[l]
    l += 1
    if cur == q:
    sz = (d - u + 1) * (r - l + 1)
    res = [(u, l), (d, r)]
    if sz < size:
        size = sz
        ans = [res]
    elif sz == size:
        ans . append(res)
    return sorted(ans)

def match(s, conns=dict(zip('ABXY', 'BAYX'))):
    dp = [[0]]
    for j, c in enumerate(s):
    dp . append([
        max([dp[j][i]] + [
            dp[k][i] + 1 + dp[j][k + 1] for k in range(i, j) if s[k] == conns[s[j]]
        ]) for i in range(j + 1)] + [0])
    return dp[- 1][0]

from itertools import product


def color(testmap):
    m = {r: i for i, r in enumerate(set(testmap . replace('\n', '')))}
    g = testmap . strip(). split('\n')
    h, w = len(g), len(g[0])
    adj = set()
    for y, x in product(range(h), range(w)):
    if y + 1 < h and g[y][x] != g[y + 1][x]:
        adj . add((g[y][x], g[y + 1][x]))
    if x + 1 < w and g[y][x] != g[y][x + 1]:
        adj . add((g[y][x], g[y][x + 1]))
    for s in range(4):
    for p in product(range(s), repeat=len(m)):
    if all(p[m[a]] != p[m[b]] for a, b in adj):
    return s
    return 4

from typing import List, Tuple, Set
from collections import defaultdict


def remove_internal(triangles: List[Tuple[int, int, int]]) - > Set[int]:
    table = defaultdict(int)
    for i, j, k in triangles:
    table[(min(i, j), max(i, j))] += 1
    table[(min(k, j), max(k, j))] += 1
    table[(min(i, k), max(i, k))] += 1
    return {k for i, j in table . items() for k in i if j == 1}

def shortest(n, edges):
    m = [0] + [float('inf')] * (n - 1)
    for start, end, weight in sorted(edges):
    if m[start] == float('inf'):
        continue
    m[end] = min(m[start] + weight, m[end])
    return - 1 if m[- 1] == float('inf') else m[- 1]

