import re


class Compiler (object):
    def __init__(self):
    self . operator = {
        "+": lambda a, b: a + b,
        "-": lambda a, b: a - b,
        "*": lambda a, b: a * b,
        "/": lambda a, b: a / b,
    }
    self . op_name = {
        "+": "AD",
        "-": "SU",
        "*": "MU",
        "/": "DI",
    }

    def compile(self, program):
    return self . pass3(self . pass2(self . pass1(program)))

    def tokenize(self, program):
    """Turn a program string into an array of tokens. Each token 
 is either '[', ']', '(', ')', '+', '-', '*', '/', a variable 
 name or a number (as a string)"""
    token_iter = (m . group(0)
                  for m in re . finditer(r'[-+*/()[\]]|[A-Za-z]+|\d+', program))
    # return [int(tok) if tok.isdigit() else tok for tok in token_iter]
    return token_iter
    def pass1(self, program):
    """Returns an un-optimized AST"""
    tokens = self . tokenize(program)
    arg_mode = False
    args = {}
    index = 0
    ast = {}
    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2,
        '(': 0,
    }
    operands = []
    operators = []

    for token in tokens:
    if token in '[]':
    arg_mode = not arg_mode
    elif arg_mode:
    args[token] = index
    index += 1
    else:
    if token in args:
    operands . append({'op': 'arg', 'n': args[token]})
    elif token . isdigit():
    operands . append({'op': 'imm', 'n': int(token)})
    else:
    if token == '(':
    operators . append(token)
    elif token == ')':
    op = operators . pop()
    while op != '(':
    b, a = operands . pop(), operands . pop()
    operands . append({'op': op, 'a': a, 'b': b})
    op = operators . pop()
    if token in '+-*/':
    while len(operators) > 0 and precedence[operators[- 1]] >= precedence[token]:
    op = operators . pop()
    b, a = operands . pop(), operands . pop()
    operands . append({'op': op, 'a': a, 'b': b})
    operators . append(token)

    while len(operators) > 0:
    op = operators . pop()
    b, a = operands . pop(), operands . pop()
    operands . append({'op': op, 'a': a, 'b': b})
    return operands[0]

    def pass2(self, ast):
    """Returns an AST with constant expressions reduced"""
    if ast['op'] in ('arg', 'imm'):
    return ast
    a = self . pass2(ast['a'])
    b = self . pass2(ast['b'])
    if a['op'] == 'imm' and b['op'] == 'imm':
    return {'op': 'imm', 'n': self . operator[ast['op']](a['n'], b['n'])}
    return {'op': ast['op'], 'a': a, 'b': b}

    def pass3(self, ast):
    """Returns assembly instructions"""
    if ast['op'] == 'imm':
    return ['IM %d' % ast['n']]
    if ast['op'] == 'arg':
    return ['AR %d' % ast['n']]

    b = self . pass3(ast['b'])
    a = self . pass3(ast['a'])
    if len(a) == 1:
    return b + ['SW'] + a + [self . op_name[ast['op']]]
    else:
    return a + ['PU'] + b + ['SW', 'PO'] + [self . op_name[ast['op']]]

